static std::mutex SystemMarks__FRAME_HEAD_STARTFinishedMutex;
static std::atomic_bool SystemMarks__FRAME_HEAD_STARTFinishedFlag = false;
static std::condition_variable SystemMarks__FRAME_HEAD_STARTFinishedCV;
void RunInitializeSystems(std::shared_ptr world) {
    Config::LoadSystem(world);
    world->ApplyDelayedRequests();
    ::CreateClockEntitySystem(world);
    world->ApplyDelayedRequests();
    Async::Manager::CreateSystem(world);
    world->ApplyDelayedRequests();
    ::CreateFPSSettingsEntitySystem(world);
    world->ApplyDelayedRequests();
    SystemMarks::CreateConnectionEntitySystem(world);
    world->ApplyDelayedRequests();
    ::CreateFramesCounterEntitySystem(world);
    world->ApplyDelayedRequests();
    Common::CreateECSControllerSystem(world);
    world->ApplyDelayedRequests();
    Common::Scene::Manager::CreateManagerSystem(world);
    world->ApplyDelayedRequests();
    Common::Scene::Manager::CreateLoadCommandLineSceneRequestSystem(world);
    world->ApplyDelayedRequests();
    ECS::Project::CreateSystem(world);
    world->ApplyDelayedRequests();
    ECS::File::LoadSystem(world);
    world->ApplyDelayedRequests();
    ::CreateMainWindowSystem(world);
    world->ApplyDelayedRequests();
    Resource::Manager::CreateSystem(world);
    world->ApplyDelayedRequests();
    ECS::Module::CreateModulesSystem(world);
    world->ApplyDelayedRequests();
    ECS::Module::CreateFileEntitiesSystem(world);
    world->ApplyDelayedRequests();
    ECS::File::Table::ParseSystem(world);
    world->ApplyDelayedRequests();
    ECS::File::Table::ValidateCallOrderDependeciesSystem(world);
    world->ApplyDelayedRequests();
    ECS::File::Table::CreateCallOrderAdditionalDependenciesSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::GenerateRunSystemsFileSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::GenerateTreesSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::CreateModuleIncludeFileSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::CreateProjectIncludeFileSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::GenerateProjectCPPTemplateFilesSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::GenerateCMakeFileSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::GenerateComponentUtilsFileSystem(world);
    world->ApplyDelayedRequests();
    ECS::Generator::GenerateDotGraphSystem(world);
    world->ApplyDelayedRequests();
    CPP::Tree::GenerateCodeSystem(world);
    world->ApplyDelayedRequests();
};
void RunSystems(std::shared_ptr world) {
    SystemMarks__FRAME_HEAD_STARTFinishedFlag = false;
    // Run main thread systems.
    tf::Executor executor;
    tf::Taskflow taskFlow{"Frame to frame child thread systems"};
    auto Input__CreateCursorEventsTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("Input::CreateCursorEvents");
        END_PROFILE();
    });
    Input__CreateCursorEventsTask.name("Input::CreateCursorEvents");
    auto Input__CreateKeyboardEventsTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("Input::CreateKeyboardEvents");
        END_PROFILE();
    });
    Input__CreateKeyboardEventsTask.name("Input::CreateKeyboardEvents");
    auto __CreateMouseEventsTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("::CreateMouseEvents");
        END_PROFILE();
    });
    __CreateMouseEventsTask.name("::CreateMouseEvents");
    auto Async__Manager__ChangeTaskStateTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("Async::Manager::ChangeTaskState");
        END_PROFILE();
    });
    Async__Manager__ChangeTaskStateTask.name("Async::Manager::ChangeTaskState");
    auto SystemMarks__FRAME_HEAD_STARTTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("SystemMarks::FRAME_HEAD_START");
        {
            SystemMarks::FRAME_HEAD_STARTSystem(world);
            {
                std::unique_lock lock{SystemMarks__FRAME_HEAD_STARTFinishedMutex};
                SystemMarks__FRAME_HEAD_STARTFinishedFlag = true;
            }
            SystemMarks__FRAME_HEAD_STARTFinishedCV.notify_all();
        }
        END_PROFILE();
    });
    SystemMarks__FRAME_HEAD_STARTTask.name("SystemMarks::FRAME_HEAD_START");
    auto __CreateLuaContextTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("::CreateLuaContext");
        END_PROFILE();
    });
    __CreateLuaContextTask.name("::CreateLuaContext");
    auto __IncreaseFramesCounterTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("::IncreaseFramesCounter");
        END_PROFILE();
    });
    __IncreaseFramesCounterTask.name("::IncreaseFramesCounter");
    auto Behaviour__CreateLuaContextTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("Behaviour::CreateLuaContext");
        END_PROFILE();
    });
    Behaviour__CreateLuaContextTask.name("Behaviour::CreateLuaContext");
    auto Behaviour__CallUpdateMethodTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("Behaviour::CallUpdateMethod");
        END_PROFILE();
    });
    Behaviour__CallUpdateMethodTask.name("Behaviour::CallUpdateMethod");
    auto Behaviour__CreateLuaScriptTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("Behaviour::CreateLuaScript");
        END_PROFILE();
    });
    Behaviour__CreateLuaScriptTask.name("Behaviour::CreateLuaScript");
    auto __CreateLoadLuaScriptRequestTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("::CreateLoadLuaScriptRequest");
        END_PROFILE();
    });
    __CreateLoadLuaScriptRequestTask.name("::CreateLoadLuaScriptRequest");
    auto __CreateLuaScriptEntityTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("::CreateLuaScriptEntity");
        END_PROFILE();
    });
    __CreateLuaScriptEntityTask.name("::CreateLuaScriptEntity");
    auto Resource__Manager__ProcessLoadResourceRequestTask = taskFlow.emplace([&]() {
        BEGIN_PROFILE("Resource::Manager::ProcessLoadResourceRequest");
        END_PROFILE();
    });
    Resource__Manager__ProcessLoadResourceRequestTask.name("Resource::Manager::ProcessLoadResourceRequest");
    SystemMarks__FRAME_HEAD_STARTTask.precede(__GetWindowWorkAreaResizeEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__GetWindowFramebufferResizeEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(Input__GetWindowCursorEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(Input__SendWindowCursorEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(Input__GetWindowKeyboardEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(Input__SendWindowKeyboardEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__SendWindowMouseEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__GetWindowMouseEventsTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__UpdatePreviousFrameDurationTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__UpdateTimeSinceEngineStartTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__UpdateFrameStartTimePointTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__UpdateTimeSinceEpochTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(__UpdateCurrentFrameIndexTask);
    SystemMarks__FRAME_HEAD_STARTTask.precede(SystemMarks__FRAME_HEAD_ENDTask);
    tf::Future future = executor.run(taskFlow);
    future.wait();
};

#pragma once
#include 
void RunInitializeSystems(std::shared_ptr world);
void RunSystems(std::shared_ptr world);

