            };
            std::string NameSerialize(CPP::Tree::Node::Name *CPP__Tree__Node__Name) {
                using namespace std::string_literals;
                std::string string = "CPP__Tree__Node__Name =";
                string += "{";
                string += "name=";
                string += "\"";
                string += CPP__Tree__Node__Name->name_;
                string += "\"";
                string += "}";
                return string;
            };
            Name NameParse(luabridge::LuaRef &CPP__Tree__Node__Name) {
                Name component;
                component.name_ = CPP__Tree__Node__Name["name"].cast().value();
                return component;
            };
        } // namespace Node
    } // namespace Tree
