        void GenerateCodeSystem(std::shared_ptr world) {
            GenerateCode generateCode = world;
            ECS2::ComponentsFilter excludesForEntity0;
            excludesForEntity0.SetBits();
            world->ForEachEntity(excludesForEntity0,
                                                 [&](ECS2::Entity::Id entity0Id, const CPP::File::Tag *cPP__FILE__TAG) {
                                                     BEGIN_PROFILE("GenerateCode::Update");
                                                     generateCode.Update(entity0Id, cPP__FILE__TAG);
                                                     END_PROFILE();
                                                 });
        };
