                            CPP::Tree::Type::BuiltinType, CPP::Tree::Type::Name, CPP::Tree::Type::PointerType,
                            CPP::Tree::Type::ReferenceType, CPP::Tree::Type::ArrayType, CPP::Tree::Type::FunctionType,
