namespace CPP
{
	namespace Tree
	{


		void GenerateCode::Update(
			ECS2::Entity::Id entity1id,
			const CPP::File::Tag* cPP__File__Tag1) {

			const ECS2::Entity::Id& fileEntityId = entity1id;

			std::string code;

			const ECS2::ComponentsFilter cppfileCF = GetComponentsFilter(fileEntityId);



			std::function processNode =
				[&processNode, this, &code](ECS2::Entity::Id entityId) {

				const ECS2::ComponentsFilter nodeCF = GetComponentsFilter(entityId);
				if (nodeCF.IsSet()) {
					code += "#";
					if (nodeCF.IsSet()) {
						const std::string text = GetComponent(entityId)->text_;
						code += "pragma" + CPP_SPACE_STR + text + CPP_NEWLINE_STR;
					}
					else if (nodeCF.IsSet()) {
						code += "include<" + GetComponent(entityId)->path_ + ">" + CPP_NEWLINE_STR;
					}
					else if (nodeCF.IsSet()) {
						auto* define = GetComponent(entityId);
						code += CPP_DEFINE;
						code += CPP_SPACE_STR;
						code += define->name_;
						if (!define->params_.empty()) {
							code += "(";
							bool isFirst = true;
							for (std::string paramName : define->params_) {
								if (!isFirst) {
									code += CPP_COMMA_STR;
								}
								isFirst = false;
								code += paramName;
							}
							code += ")";
						}
						if (define->bodyEntity_.IsValid()) {
							processNode(define->bodyEntity_);
						}
						else {
							code += CPP_SPACE_STR;
							code += define->rawBody_;
						}
						code += CPP_NEWLINE_STR;
					}
					else {
						NOT_IMPLEMENTED();
					}
				}
				else if (nodeCF.IsSet()) {
					auto* comment = GetComponent(entityId);
					if (comment->type_ == CPP::Tree::CommentType::OneLine) {
						code += CPP_NEWLINE_STR + "//" + comment->text_ + CPP_NEWLINE_STR;
					}
					else if (comment->type_ == CPP::Tree::CommentType::Multiline) {
						code += "/*" + comment->text_ + "*/";
					}
					else {
						NOT_IMPLEMENTED();
					}

				}
				else if (nodeCF.IsSet()) {
					ASSERT(nodeCF.IsSet());

					code += "namespace " + GetComponent(entityId)->name_ + "{";
					if (nodeCF.IsSet()) {
						const auto* childNodes = GetComponent(entityId);
						for (ECS2::Entity::Id childNodeEntityId : childNodes->ids_) {
							processNode(childNodeEntityId);
						}
					}
					code += "}";
				}
				else if (nodeCF.IsSet()) {
					ASSERT(nodeCF.IsSet());
					const auto* variable = GetComponent(entityId);

					ASSERT(variable->type_ != ECS2::Entity::Id::invalid_);

					if (nodeCF.IsSet()) {
						code += CPP_PUBLIC_STR + CPP_SPACE_STR;
					}
					if (nodeCF.IsSet()) {
						code += CPP_PRIVATE_STR + CPP_SPACE_STR;
					}
					if (nodeCF.IsSet()) {
						code += CPP_STATIC_STR + CPP_SPACE_STR;
					}

					if (nodeCF.IsSet()) {
						code += CPP_CONSTEXPR_STR + CPP_SPACE_STR;
					}
					if (nodeCF.IsSet()) {
						code += CPP_CONST_STR + CPP_SPACE_STR;
					}
					//Type.
					ASSERT(IsComponentExist(variable->type_));
					processNode(variable->type_);
					code += CPP_SPACE_STR;
					code += GetComponent(entityId)->name_;

					//Initializer.
					if (variable->initializer_.IsValid()) {
						if (IsComponentExist(variable->initializer_)) {
							processNode(variable->initializer_);
						}
						else {
							ASSERT(IsComponentExist(variable->initializer_));
							code += "=";
							processNode(variable->initializer_);
						}
					}
					code += ";";

				}
				else if (nodeCF.IsSet()) {
					if (IsComponentExist(entityId)) {
						code += CPP_CONST_STR;
						code += CPP_SPACE_STR;
					}
					if (nodeCF.IsSet()) {
						code += GetComponent(entityId)->name_;
					}
					else if (nodeCF.IsSet()) {
						const auto* templateSpecializationType = GetComponent(entityId);
						processNode(templateSpecializationType->baseType_);
						code += "<";
						bool isFirst = true;
						for (ECS2::Entity::Id templateArg : templateSpecializationType->templateArgs_) {
							if (!isFirst) {
								code += ",";
							}
							processNode(templateArg);
							isFirst = false;
						}
						code += ">";
					}
					else if (nodeCF.IsSet()) {
						const auto* builtinType = GetComponent(entityId);
						if (builtinType->type_ == CPP::Tree::Type::BuiltinTypes::Void) {
							code += CPP_VOID_STR;
						}
						else if (builtinType->type_ == CPP::Tree::Type::BuiltinTypes::Char) {
							code += CPP_CHAR_STR;
						}
						else if (builtinType->type_ == CPP::Tree::Type::BuiltinTypes::Bool) {
							code += CPP_BOOL_STR;
						}
						else if (builtinType->type_ == CPP::Tree::Type::BuiltinTypes::Float) {
							code += CPP_FLOAT_STR;
						}
						else {
							NOT_IMPLEMENTED();
						}
					}
					else if (nodeCF.IsSet()) {
						const auto* pointerType = GetComponent(entityId);
						processNode(pointerType->pointer_);
						code += "*";
					}
					else if (nodeCF.IsSet()) {
						const auto* referenceType = GetComponent(entityId);
						processNode(referenceType->id_);
						if (referenceType->isRValue_) {
							code += "&&";
						}
						else {
							code += "&";
						}
					}
					else {
						NOT_IMPLEMENTED();
					}
				}
				else if (nodeCF.IsSet()) {

					if (nodeCF.IsSet()) {
						code += CPP_PUBLIC_STR + CPP_SPACE_STR;
					}
					if (nodeCF.IsSet()) {
						code += CPP_PRIVATE_STR + CPP_SPACE_STR;
					}

					if (IsComponentExist(entityId) || IsComponentExist(entityId)) {
						ASSERT(!nodeCF.IsSet());
						std::vector templateParamEntityIds;
						if (IsComponentExist(entityId)) {
							templateParamEntityIds = GetComponent(entityId)->templateParams_;
						}

						if (!templateParamEntityIds.empty() || IsComponentExist(entityId)) {
							code += "template";
							code += "<";
							bool isFirst = true;
							for (ECS2::Entity::Id templateParamEntityId : templateParamEntityIds) {
								if (!isFirst) {
									code += ",";
								}
								isFirst = false;
								const auto* templateTypeParam = GetComponent(templateParamEntityId);
								code += CPP_CLASS_STR;
								if (templateTypeParam->isParameterPack_) {
									code += "...";
									ASSERT(templateTypeParam->defaultType_.IsInvalid());
								}
								code += CPP_SPACE_STR;
								processNode(templateParamEntityId);
								if (templateTypeParam->defaultType_.IsValid()) {
									code += "=";
									code += CPP_SPACE_STR;
									processNode(templateTypeParam->defaultType_);
								}
							}
							code += ">";
						}
					}

					if (nodeCF.IsSet()) {
						code += CPP_CONSTEXPR_STR + CPP_SPACE_STR;
					}

					if (nodeCF.IsSet()) {
						code += CPP_STATIC_STR + CPP_SPACE_STR;
					}

					if (nodeCF.IsSet()) {
						code += CPP_INLINE_STR + CPP_SPACE_STR;
					}

					//For constructor returnType_ will be ECS2::Entity::Id::invalid_.
					if (GetComponent(entityId)->returnType_ != ECS2::Entity::Id::invalid_) {
						ECS2::Entity::Id returnTypeEntityId = GetComponent(entityId)->returnType_;
						ASSERT(IsComponentExist(returnTypeEntityId));
						processNode(returnTypeEntityId);//TODO: replace with PointerType
						code += CPP_SPACE_STR;
					}

					if (nodeCF.IsSet()) {
						const ECS2::Entity::Id parentEntityId = GetComponent(entityId)->parentDecl_;
						if (parentEntityId.IsValid()) {
							code += GetComponent(parentEntityId)->name_;
							code += "::";
						}
					}

					code += GetComponent(entityId)->name_;

					if (IsComponentExist(entityId)) {
						ASSERT(!nodeCF.IsSet());
						std::vector explicitTemplateParamEntityIds = GetComponent(entityId)->templateArgs_;
						if (!explicitTemplateParamEntityIds.empty()) {
							code += "<";
							bool isFirst = true;
							for (ECS2::Entity::Id explicitTemplateParamEntityId : explicitTemplateParamEntityIds) {
								if (!isFirst) {
									code += ",";
									code += CPP_SPACE_STR;
								}
								isFirst = false;
								processNode(explicitTemplateParamEntityId);
							}
							code += ">";
						}
					}


					code += "(";
					if (IsComponentExist(entityId)) {
						//Parameters.
						bool isFirst = true;
						for (ECS2::Entity::Id maybeConstructorParameter : GetComponent(entityId)->ids_) {
							if (IsComponentExist(maybeConstructorParameter)) {
								ECS2::Entity::Id& constructorParameter = maybeConstructorParameter;
								ASSERT(IsComponentExist(constructorParameter));
								ASSERT(IsComponentExist(constructorParameter));
								const auto* nameTypeInitializer = GetComponent(constructorParameter);
								ASSERT(nameTypeInitializer->type_.IsValid());
								ASSERT(IsComponentExist(nameTypeInitializer->type_));

								if (!isFirst) {
									code += ",";
								}
								processNode(maybeConstructorParameter);
								isFirst = false;

							}
						}
					}
					code += ")";
					if (nodeCF.IsSet()) {
						if (IsComponentExist(entityId)) {
							const auto* initList = GetComponent(entityId);
							code += ":";
							bool isFirst = true;
							for (ECS2::Entity::Id initializer : initList->initializers_) {
								ECS2::Entity::Id memberEntityId = GetComponent(initializer)->member_;


								if (!isFirst) {
									code += ",";
								}
								isFirst = false;
								code += GetComponent(memberEntityId)->name_;

								code += "{";
								ECS2::Entity::Id exprEntityId = GetComponent(initializer)->initExpr_;
								processNode(exprEntityId);
								//ECS2::ComponentsFilter exprCF = GetComponentsFilter(exprEntityId);
								//if (IsComponentExist(exprEntityId)) {
								//	code += GetComponent(exprEntityId)->name_;
								//}
								//else  if (IsComponentExist(exprEntityId)) {
								//	ECS2::Entity::Id parameterEntityId = GetComponent(exprEntityId)->targetDecl_;
								//	code += GetComponent(parameterEntityId)->name_;
								//}
								//else if (IsComponentExist(exprEntityId)) {
								//	code += GetComponent(exprEntityId)->value_;
								//	//TODO: add types validation.
								//}
								//else {
								//	NOT_IMPLEMENTED();
								//}
								code += "}";

							}

						}
					}
					if (IsComponentExist(entityId)) {
						for (ECS2::Entity::Id maybeBody : GetComponent(entityId)->ids_) {
							if (IsComponentExist(maybeBody)) {
								ASSERT(IsComponentExist(maybeBody));
								processNode(maybeBody);

							}
						}
					}
					code += ";";
				}
				else if (nodeCF.IsSet()) {
					const auto* templateTypeParam = GetComponent(entityId);
					code += templateTypeParam->name_;
				}
				else if (nodeCF.IsSet()) {
					const auto* usingDirective = GetComponent(entityId);
					code += "using namespace" + CPP_SPACE_STR + usingDirective->namespaceName_ + ";";
				}
				else if (nodeCF.IsSet()) {
					ASSERT(nodeCF.IsSet());
					code += CPP_CLASS_STR + CPP_SPACE_STR + GetComponent(entityId)->name_;

					if (IsComponentExist(entityId)) {
						auto classChilds = GetComponent(entityId)->ids_;
						if (!classChilds.empty()) {
							code += "{";
							for (ECS2::Entity::Id classChildEntityId : classChilds) {
								ECS2::ComponentsFilter childComponentsFilter = GetComponentsFilter(classChildEntityId);
								if (childComponentsFilter.IsSet()) {
									processNode(classChildEntityId);
								}
								else if (childComponentsFilter.IsSet()) {
									processNode(classChildEntityId);
								}

							}
							code += "}";
						}

					}
					code += ";";
				}
				else if (nodeCF.IsSet()) {
					ASSERT(nodeCF.IsSet());
					code += CPP_ENUM_STR + CPP_SPACE_STR + CPP_CLASS_STR + CPP_SPACE_STR + GetComponent(entityId)->name_;
					code += "{";
					bool isFirst = true;
					for (ECS2::Entity::Id enumeratorEntityId : GetComponent(entityId)->ids_) {
						if (!isFirst) {
							code += ",";
						}
						processNode(enumeratorEntityId);
						isFirst = false;
					}
					code += "};";
				}
				else if (nodeCF.IsSet()) {
					ASSERT(nodeCF.IsSet());
					const auto* enumerator = GetComponent(entityId);
					code += enumerator->name_;
					if (enumerator->valueExpr_.IsValid()) {
						NOT_IMPLEMENTED();
					}
				}
				else if (nodeCF.IsSet()) {
					if (nodeCF.IsSet()) {
						code += "{";
						for (ECS2::Entity::Id childStmtEntityId : GetComponent(entityId)->ids_) {
							processNode(childStmtEntityId);
						}
						code += "}";
					}
					else if (nodeCF.IsSet()) {
						code += CPP_RETURN_STR + CPP_SPACE_STR;
						ECS2::Entity::Id returnExpr = GetComponent(entityId)->expr_;
						processNode(returnExpr);
						code += ";";
					}
					else if (nodeCF.IsSet()) {
						ECS2::Entity::Id exprEntityId = GetComponent(entityId)->expr_;
						ASSERT(exprEntityId.IsValid());
						processNode(exprEntityId);
						code += ";";
					}
					else {
						NOT_IMPLEMENTED();
					}
				}
				else if (nodeCF.IsSet()) {
					if (nodeCF.IsSet()) {
						code += GetComponent(entityId)->value_;
					}
					else if (nodeCF.IsSet()) {
						code += GetComponent(entityId)->name_;
					}
					else if (nodeCF.IsSet()) {
						const auto* lambda = GetComponent(entityId);
						code += "[";
						{//Capture list
							if (lambda->captureType_ != CPP::Tree::Expr::CaptureType::Undefined) {
								if (lambda->captureType_ == CPP::Tree::Expr::CaptureType::ByReference) {
									code += "&";
								}
								else if (lambda->captureType_ == CPP::Tree::Expr::CaptureType::ByValue) {
									code += "=";
								}
								if (!lambda->captureList_.empty()) {
									code += ",";
								}
							}
							bool isFirst = true;
							for (const auto& capture : lambda->captureList_) {
								if (!isFirst) {
									code += ",";
								}
								isFirst = false;
								if (capture.captureType_ == CPP::Tree::Expr::CaptureType::ByReference) {
									code += "&";
								}
								else if (capture.captureType_ == CPP::Tree::Expr::CaptureType::ByValue) {
									//Do nothing.
								}
								else {
									ASSERT_FAIL();
								}
								processNode(capture.decl_);
							}
						}
						code += "]";
						code += "(";

						{//Parameters
							bool isFirst = true;
							for (const auto& parameterEntityId : lambda->parameters_) {
								if (!isFirst) {
									code += ",";
								}
								isFirst = false;

								processNode(parameterEntityId);
							}
						}
						code += ")";
						//code += "{";
						{
							processNode(lambda->body_);
						}
						//code += "}";
					}
					else if (nodeCF.IsSet()) {
						const auto* callExpr = GetComponent(entityId);
						processNode(callExpr->callee_);
						if (!callExpr->templateArgs_.empty()) {
							code += "<";
							bool isFirst = true;
							for (ECS2::Entity::Id typeEntityId : callExpr->templateArgs_) {
								if (!isFirst) {
									code += ",";
								}
								isFirst = false;
								processNode(typeEntityId);
								if (IsComponentExist(typeEntityId)) {
									const auto* templateTypeParam = GetComponent(typeEntityId);
									if (templateTypeParam->isParameterPack_) {
										code += "...";
									}
								}
							}
							code += ">";
						}
						code += "(";
						bool isFirst = true;
						for (ECS2::Entity::Id argEntityId : callExpr->arguments_) {
							if (!isFirst) {
								code += ",";
							}
							isFirst = false;
							processNode(argEntityId);
						}
						code += ")";
					}
					else if (nodeCF.IsSet()) {
						const auto* memberAccess = GetComponent(entityId);
						processNode(memberAccess->object_);
						if (memberAccess->isArrow_) {
							code += "->";
						}
						else {
							code += ".";
						}
						code += memberAccess->memberName_;
					}
					else if (nodeCF.IsSet()) {
						const auto* invocation = GetComponent(entityId);
						code += invocation->name_;
						code += "(";
						bool isFirst = true;
						for (auto& argument : invocation->arguments_) {
							if (!isFirst) {
								code += ", ";
							}
							isFirst = false;
							processNode(argument);
						}
						code += ")";
					}
					else if (nodeCF.IsSet()) {
						const auto* templateId = GetComponent(entityId);
						code += templateId->name_;
						code += "<";
						bool isFirst = true;
						for (auto& argument : templateId->templateArgs_) {
							if (!isFirst) {
								code += ", ";
							}
							isFirst = false;
							processNode(argument);
						}
						code += ">";
					}
					else if (nodeCF.IsSet()) {
						const auto* unaryOp = GetComponent(entityId);
						if (unaryOp->operation_ == CPP::Tree::Expr::UnaryOpType::AddressOf) {
							code += "&";
						}
						else {
							NOT_IMPLEMENTED();
						}
						processNode(unaryOp->operand_);
					}
					else if (nodeCF.IsSet()) {
						const auto* binaryOp = GetComponent(entityId);
						ASSERT(binaryOp->left_.IsValid());
						ASSERT(binaryOp->right_.IsValid());
						if (binaryOp->operation_ == CPP::Tree::Expr::BinaryOpType::Plus) {
							processNode(binaryOp->left_);
							code += "+";
							processNode(binaryOp->right_);
						}
						else if (binaryOp->operation_ == CPP::Tree::Expr::BinaryOpType::PlusAssign) {
							processNode(binaryOp->left_);
							code += "+=";
							processNode(binaryOp->right_);
						}
						else if (binaryOp->operation_ == CPP::Tree::Expr::BinaryOpType::Assign) {
							processNode(binaryOp->left_);
							code += "=";
							processNode(binaryOp->right_);
						}
						else {
							NOT_IMPLEMENTED();
						}
					}
					else if (nodeCF.IsSet()) {
						const auto* arraySubscript = GetComponent(entityId);
						processNode(arraySubscript->array_);
						code += "[";
						processNode(arraySubscript->index_);
						code += "]";
					}
					else if (nodeCF.IsSet()) {
						code += "{";
						const auto* initList = GetComponent(entityId);
						bool isFirst = true;
						for (auto element : initList->elements_) {
							if (!isFirst) {
								code += ",";
							}
							isFirst = false;
							processNode(element);
						}
						code += "}";
					}
					else if (nodeCF.IsSet()) {

						auto* memberPtrExpr = GetComponent(entityId);
						code += "&";
						processNode(memberPtrExpr->classType_);
						code += "::";
						code += memberPtrExpr->memberName_;
					}
					else if (nodeCF.IsSet()) {
						ECS2::Entity::Id pattern = GetComponent(entityId)->pattern_;
						processNode(pattern);
						code += "...";
					}
					else if (nodeCF.IsSet()) {
						ECS2::Entity::Id innerExpr = GetComponent(entityId)->innerExpr_;
						code += "(";
						processNode(innerExpr);
						code += ")";
					}
					else {
						NOT_IMPLEMENTED();
					}
				}
				else if (nodeCF.IsSet()) {
					const auto* nameTypeInitializer = GetComponent(entityId);
					processNode(nameTypeInitializer->type_);
					if (nameTypeInitializer->isParameterPack_) {
						code += "...";
					}
					code += CPP_SPACE_STR;
					code += nameTypeInitializer->name_;

				}
				else {
					NOT_IMPLEMENTED();
				}


				};

			if (IsComponentExist(fileEntityId)) {
				const auto* fileRootNodes = GetComponent(fileEntityId);

				for (ECS2::Entity::Id rootNodeEntityId : fileRootNodes->ids_) {
					processNode(rootNodeEntityId);
				}

				//FORMATTIG
				{
					clang::format::FormatStyle style = clang::format::getMicrosoftStyle(clang::format::FormatStyle::LanguageKind::LK_Cpp);
					{
						style.AlignEscapedNewlines = clang::format::FormatStyle::EscapedNewlineAlignmentStyle::ENAS_DontAlign;
						style.NamespaceIndentation = clang::format::FormatStyle::NI_All;
						style.BreakBeforeBraces = clang::format::FormatStyle::BS_Custom;
						style.BraceWrapping.AfterNamespace = false; // Скобка namespace на той же строке
						style.BraceWrapping.AfterClass = false;     // Скобка class на той же строке
						style.BraceWrapping.AfterStruct = false;    // Скобка struct на той же строке
						style.BraceWrapping.AfterEnum = false;      // Скобка enum на той же строке
						style.BraceWrapping.AfterFunction = false;
						//style.MacroBlockBegin
						//style.AlignConsecutiveMacros 
						//style.ColumnLimit
					}

					llvm::StringRef codeToFormat = code.c_str();  // ������ ������ ����

					// ���������� �������� ��� ����� ����
					clang::tooling::Replacements replacements = clang::format::reformat(style, codeToFormat, { clang::tooling::Range(0, codeToFormat.size()) });

					auto formattedCode = clang::tooling::applyAllReplacements(codeToFormat, replacements);
					if (!formattedCode) {
						llvm::errs() << "Error formatting the code.\n";
					}
					code = *formattedCode;
				}
			}

			//CREATE FILE.
			const auto* path = GetComponent(fileEntityId);
			const auto* name = GetComponent(fileEntityId);

			auto osFile = std::make_shared(path->path_ / std::filesystem::path(name->name_ + std::string{ (cppfileCF.IsSet()) ? (".hpp") : (".cpp") }));
			osFile->Create();
			*osFile << code;


		}
	}

