//#define CPP__TREE__CREATE_ENTITIES_VECTOR(...)std::vector{__VA_ARGS__}

namespace CPP__TREE__DETAIL {

    // ��������� ECS2::Entity::Id � ����� ��� ���� �������.
    inline void AppendEntity(std::vector& out, ECS2::Entity::Id id) {
        out.push_back(id);
    }

    // lvalue-������ � ��������� ������������.
    inline void AppendEntity(std::vector& out,
        const std::vector& ids) {
        out.insert(out.end(), ids.begin(), ids.end());
    }

    // rvalue-������ � ��������� ������������; ��� ������� out ����� ������� �����.
    inline void AppendEntity(std::vector& out,
        std::vector&& ids) {
        if (out.empty()) {
            out = std::move(ids);
        }
        else {
            out.insert(out.end(),
                std::make_move_iterator(ids.begin()),
                std::make_move_iterator(ids.end()));
        }
    }

    template
    inline constexpr bool is_valid_entities_vector_arg_v =
        std::is_same_v<std::decay_t, ECS2::Entity::Id> ||
        std::is_same_v<std::decay_t, std::vector>;

} // namespace CPP__TREE__DETAIL


/**
 * �������� ������� std::vector �� ����������.
 *
 * ���������� ���������:
 *   - ECS2::Entity::Id         (������� ��� ���� �������)
 *   - std::vector   (��� �������� ��������������� � ���������)
 *
 * �������:
 *   CPP__TREE__CREATE_ENTITIES_VECTOR()                                  // {}
 *   CPP__TREE__CREATE_ENTITIES_VECTOR(a, b, c)                           // {a, b, c}
 *   CPP__TREE__CREATE_ENTITIES_VECTOR(a, vec1, b, std::move(vec2))       // a + vec1 + b + vec2
 */
template
std::vector CPP__TREE__CREATE_ENTITIES_VECTOR(Args&&... args) {
    static_assert(
        (CPP__TREE__DETAIL::is_valid_entities_vector_arg_v && ...),
        "CPP__TREE__CREATE_ENTITIES_VECTOR accepts only ECS2::Entity::Id "
        "and std::vector"
        );

    // 1. ��������� ������ ������, ����� ������� ���� reserve.
    auto countHint = [](auto&& x) -> std::size_t {
        using T = std::decay_t;
        if constexpr (std::is_same_v<T, std::vector>) {
            return x.size();
        }
        else {
            return 1u;
        }
        };

    std::size_t total = 0;
    ((total += countHint(args)), ...);   // args ��� lvalue: ������ ������

    std::vector result;
    result.reserve(total);

    // 2. ���������: std::forward ��� move ��� rvalue-��������/ID.
    (CPP__TREE__DETAIL::AppendEntity(result, std::forward(args)), ...);

    return result;
}

template
ECS2::Entity::Id CPP__TREE__COMMENT__CREATE_ONE_LINE_COMMENT(System* system, const std::string& str) {
	ECS2::Entity::Id comment = system->CreateEntity();
	system->CreateComponent(comment, str, CPP::Tree::CommentType::OneLine);
	return comment;
}

template
ECS2::Entity::Id CPP__TREE__COMMENT__CREATE_CLANG_FORMAT_OFF_COMMENT(System* system) {
	ECS2::Entity::Id comment = system->CreateEntity();
	system->CreateComponent(comment, ::std::string{ " clang-format off" }, CPP::Tree::CommentType::OneLine);
	return comment;
}

template
ECS2::Entity::Id CPP__TREE__COMMENT__CREATE_CLANG_FORMAT_ON_COMMENT(System* system) {
	ECS2::Entity::Id comment = system->CreateEntity();
	system->CreateComponent(comment, ::std::string{ " clang-format on\n" }, CPP::Tree::CommentType::OneLine);
	return comment;
}


/*					PREPROCESSOR					*/
#define CPP__TREE__PREPROCESSOR__CREATE_PRAGMA(str)\
	[this](const std::string& text){\
		ECS2::Entity::Id pragma = CreateEntity();\
		CreateComponent(pragma);\
		CreateComponent(pragma, text);\
		return pragma;\
	}(str)

#define CPP__TREE__PREPROCESSOR__CREATE_PRAGMA_OPTIMIZE()\
	[this](){\
		ECS2::Entity::Id pragmaOptimize = CreateEntity();\
		CreateComponent(pragmaOptimize);\
		CreateComponent(pragmaOptimize, "optimize");\
		return pragmaOptimize;\
	}()

template
ECS2::Entity::Id CPP__TREE__PREPROCESSOR__CREATE_PRAGMA_ONCE(System* system) {
	ECS2::Entity::Id pragmaOptimize = system->CreateEntity();
	system->template CreateComponent(pragmaOptimize);
	system->template CreateComponent(pragmaOptimize, "once");
	return pragmaOptimize;
}

template
ECS2::Entity::Id CPP__TREE__PREPROCESSOR__CREATE_INCLUDE(System* system, const std::string& text) {
	ECS2::Entity::Id includeEntityId = system->CreateEntity();
	system->template CreateComponent(includeEntityId);
	system->template CreateComponent(includeEntityId, text, false);
	return includeEntityId;
}

#define CPP__TREE__PREPROCESSOR__CREATE_DEFINE(name, params, bodyStr, bodyEntity, isFunction)\
	[this](const std::string& nameStr, const std::vector& parameters, const std::string& bodyString, ECS2::Entity::Id bodyEntityId, bool isFunctionLike){\
		ECS2::Entity::Id macrosEntityId = CreateEntity();\
		CreateComponent(macrosEntityId);\
		CreateComponent(macrosEntityId,nameStr, parameters, bodyString, bodyEntityId, isFunctionLike);\
		return macrosEntityId;\
	}(name, params, bodyStr, bodyEntity, isFunction)


