        void LoadSystem(std::shared_ptr world) {
            Load load = world;
            ECS2::ComponentsFilter excludesForEntity0;
            excludesForEntity0.SetBits();
            world->ForEachEntity<::CommandLineParameters, ECS::ProjectFilePath>(
                excludesForEntity0,
                [&](ECS2::Entity::Id entity0Id, const ::CommandLineParameters *__COMMANDLINEPARAMETERS,
                    const ECS::ProjectFilePath *eCS__PROJECTFILEPATH) {
                    BEGIN_PROFILE("Load::Update");
                    load.Update(entity0Id, __COMMANDLINEPARAMETERS, eCS__PROJECTFILEPATH);
                    END_PROFILE();
                });
        };
    } // namespace File
} // namespace ECS
