            void CreateCallOrderAdditionalDependenciesSystem(std::shared_ptr world) {
                CreateCallOrderAdditionalDependencies createCallOrderAdditionalDependencies = world;
                ECS2::ComponentsFilter excludesForEntity0;
                excludesForEntity0.SetBits();
                world->ForEachEntity(
                    excludesForEntity0, [&](ECS2::Entity::Id entity0Id, const ECS::Project::Tag *eCS__PROJECT__TAG,
                                            const ECS::Project::Path *eCS__PROJECT__PATH,
                                            const Behaviour::LuaScript *bEHAVIOUR__LUASCRIPT) {
                        BEGIN_PROFILE("CreateCallOrderAdditionalDependencies::Update");
                        createCallOrderAdditionalDependencies.Update(entity0Id, eCS__PROJECT__TAG, eCS__PROJECT__PATH,
                                                                     bEHAVIOUR__LUASCRIPT);
                        END_PROFILE();
                    });
