            void ParseSystem(std::shared_ptr world) {
                Parse parse = world;
                ECS2::ComponentsFilter excludesForEntity0;
                excludesForEntity0.SetBits();
                ECS2::ComponentsFilter excludesForEntity1;
                excludesForEntity1.SetBits();
                world->ForEachEntity(
                    excludesForEntity0, [&](ECS2::Entity::Id entity0Id, const ECS::Project::Tag *eCS__PROJECT__TAG,
                                            const ECS::Project::Path *eCS__PROJECT__PATH,
                                            const Behaviour::LuaScript *bEHAVIOUR__LUASCRIPT) {
                        world->ForEachEntity(
                            excludesForEntity1, [&](ECS2::Entity::Id entity1Id, const ECS::File::Tag *eCS__FILE__TAG,
                                                    const ECS::File::Path *eCS__FILE__PATH,
                                                    const ECS::Module::EntityId *eCS__MODULE__ENTITYID,
                                                    const Behaviour::LuaScript *bEHAVIOUR__LUASCRIPT) {
                                BEGIN_PROFILE("Parse::Update");
                                parse.Update(entity0Id, eCS__PROJECT__TAG, eCS__PROJECT__PATH, bEHAVIOUR__LUASCRIPT,
                                             entity1Id, eCS__FILE__TAG, eCS__FILE__PATH, eCS__MODULE__ENTITYID,
                                             bEHAVIOUR__LUASCRIPT);
                                END_PROFILE();
                            });
                    });
            };
