	namespace Table {
		void Parse::Update(
			ECS2::Entity::Id entity0id,
			const ECS::Project::Tag* eCS__Project__Tag0,
			const ECS::Project::Path* eCS__Project__Path0,
			const Behaviour::LuaScript* luaScript0,

			ECS2::Entity::Id entity1id,
			const ECS::File::Tag* eCS__File__Tag1,
			const ECS::File::Path* eCS__File__Path1,
			const ECS::Module::EntityId* eCS__Module__EntityId1,
			const Behaviour::LuaScript* luaScript1) {

			::Lua::Script script{ luaScript1->text_ };

			::Lua::Context context;
			auto abtractionDefinionsOrder = GetTablesOrder(luaScript1->text_);
			std::unordered_map abstractionNameToOrderIndex;
			auto getFullName = [](const std::vector& namespaceNames, const std::string& abstractionName) {
				std::string fullName;
				for (const auto& namespaceName : namespaceNames) {
					fullName = fullName + namespaceName + "::";
				}
				return fullName + abstractionName;
				};
			for (Common::Index i = 0; i < abtractionDefinionsOrder.size(); i++) {
				abstractionNameToOrderIndex[abtractionDefinionsOrder[i]] = i;
			}
			context.LoadScript(script);
			luabridge::LuaRef ecsFile = luabridge::getGlobal(context.state_, "_G");


			//std::map abstractionToOrder = GetStructDeclarationOrder(luaScript1->text_);

			std::vector disableTags;
			if (IsComponentExist(entity1id)) {
				disableTags = GetComponent(entity1id)->disableTags_;
			}



			if (!abtractionDefinionsOrder.empty()) {
				Common::BreakPointLine();
			}

			std::vector parsedTables;
			{
				std::function<ECS2::Entity::Id(const std::string&, luabridge::LuaRef, std::vector&)> processTable
					= [&](
						const std::string& name,
						luabridge::LuaRef table,
						std::vector& fullName) {

							if (name.ends_with("Namespace")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								ECS2::Entity::Id namespaceTableEntityId = CreateEntity();
								const std::string namespaceName = name.substr(0, name.rfind("Namespace"));

								CreateComponent(namespaceTableEntityId);
								CreateComponent(namespaceTableEntityId);
								CreateComponent(namespaceTableEntityId, namespaceName);
								fullName.push_back(namespaceName);

								std::vector parsedNamespaceTables;

								for (auto it = luabridge::Iterator(table); !it.isNil(); ++it) {
									luabridge::LuaRef key = it.key();
									luabridge::LuaRef value = it.value();

									if (value.isTable() ||
										value.isString()/*For aliases*/) {
										if (key.isString()) {
											const std::string tableName = key.tostring();
											//TODO: move setting of child table to processTable function.
											ECS2::Entity::Id parsedTable = processTable(tableName, value, fullName);
											if (parsedTable.IsValid()) {
												CreateComponent(parsedTable, namespaceTableEntityId);
												CreateComponent(parsedTable, entity1id);
												parsedNamespaceTables.push_back(parsedTable);
											}

										}
									}
								}
								fullName.pop_back();


								CreateComponent(
									namespaceTableEntityId,
									parsedNamespaceTables);

								return namespaceTableEntityId;
							}
							else if (name.ends_with("Struct")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								ECS2::Entity::Id structEntityId = [&](luabridge::LuaRef component,
									const std::string& structName) {


										ECS2::Entity::Id structEntityId = CreateEntity();
										CreateComponent(structEntityId);
										CreateComponent(structEntityId);
										CreateComponent(structEntityId, structName.substr(0, structName.rfind("Struct")));
										CreateComponent(structEntityId, abstractionNameToOrderIndex[getFullName(fullName, structName.substr(0, structName.rfind("Struct")))]);

										Common::Size alignment = Common::Limits::Max();
										luabridge::LuaRef alignmentRef = component["alignment"];
										if (!alignmentRef.isNil()) {
											alignment = alignmentRef.cast().value();
											if (alignment != Common::Limits::Max()) {
												CreateComponent(structEntityId, alignment);
											}
										}
										luabridge::LuaRef fields = component["fields"];


										if (!fields.isNil()) {
											std::vector parsedFieldsEntityIds;
											std::vector<std::pair> tablesNames;
											for (luabridge::Iterator it(fields); !it.isNil(); ++it) {
												luabridge::LuaRef field = it.value();

												ECS2::Entity::Id fieldEntityId = CreateEntity();
												CreateComponent(fieldEntityId);
												CreateComponent(fieldEntityId, field["type"].cast().value());
												CreateComponent(fieldEntityId, field["name"].cast().value());

												if (!field["defaultValue"].isNil()) {
													CreateComponent(fieldEntityId, field["defaultValue"].cast().value());
												}

												if (!field["alignment"].isNil()) {
													CreateComponent(fieldEntityId, field["alignment"].cast().value());
												}

												if (!field["copyable"].isNil()) {
													CreateComponent(fieldEntityId, field["copyable"].cast().value());
												}

												parsedFieldsEntityIds.push_back(fieldEntityId);
											}
											CreateComponent(structEntityId, parsedFieldsEntityIds);
										}

										return structEntityId;
									}(table, name);

								return structEntityId;

							}
							else if (name.ends_with("Enum")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								ECS2::Entity::Id enumEntityId = [&](luabridge::LuaRef enumRef,
									const std::string& enumName) {

										ECS2::Entity::Id enumEntityId = CreateEntity();
										CreateComponent(enumEntityId);
										CreateComponent(enumEntityId);
										CreateComponent(enumEntityId, enumName.substr(0, enumName.rfind("Enum")));
										CreateComponent(enumEntityId, abstractionNameToOrderIndex[getFullName(fullName, enumName.substr(0, enumName.rfind("Enum")))]);
										luabridge::LuaRef values = enumRef["values"];

										std::vector parsedValues;

										if (!values.isNil()) {
											for (luabridge::Iterator it(values); !it.isNil(); ++it) {
												luabridge::LuaRef valueRef = it.value();
												parsedValues.push_back(valueRef.cast().value());
											}
										}
										CreateComponent(enumEntityId, parsedValues);
										return enumEntityId;
									}(table, name);

								return enumEntityId;
							}
							else if (name.ends_with("Component")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								ECS2::Entity::Id componentEntityId = [&](luabridge::LuaRef component,
									const std::string& componentName) {

										ASSERT_FMSG(std::isupper(componentName[0]), "First component name symbol must be uppercase.");

										ECS2::Entity::Id componentEntityId = CreateEntity();
										CreateComponent(componentEntityId);
										CreateComponent(componentEntityId);
										CreateComponent(componentEntityId, componentName.substr(0, componentName.rfind("Component")));
										CreateComponent(componentEntityId, abstractionNameToOrderIndex[getFullName(fullName, componentName.substr(0, componentName.rfind("Component")))]);

										bool isString = component.isString();
										auto castResult = component.cast();
										if (castResult) {
											std::string aliasFor = castResult.value();
											CreateComponent(componentEntityId, aliasFor);
										}
										bool serializable = true;
										luabridge::LuaRef serializableRef = component["serializable"];
										if (!serializableRef.isNil()) {
											serializable = serializableRef.cast().value();
											if (serializable) {
												CreateComponent(componentEntityId);
											}
										}
										bool bindable = true;
										luabridge::LuaRef bindableRef = component["bindable"];
										if (!bindableRef.isNil()) {
											bindable = bindableRef.cast().value();
											if (bindable) {
												CreateComponent(componentEntityId);
											}
										}
										Common::Size alignment = Common::Limits::Max();
										luabridge::LuaRef alignmentRef = component["alignment"];
										if (!alignmentRef.isNil()) {
											alignment = alignmentRef.cast().value();
											if (alignment != Common::Limits::Max()) {
												CreateComponent(componentEntityId, alignment);
											}
										}
										bool manualEditFunction = false;
										luabridge::LuaRef manualEditFunctionRef = component["manualEditFunction"];
										if (!manualEditFunctionRef.isNil()) {
											manualEditFunction = manualEditFunctionRef.cast().value();
											if (manualEditFunction) {
												CreateComponent(componentEntityId);
											}
										}
										bool manualBindFunction = false;
										luabridge::LuaRef manualBindFunctionRef = component["manualBindFunction"];
										if (!manualBindFunctionRef.isNil()) {
											manualBindFunction = manualBindFunctionRef.cast().value();
											if (manualBindFunction) {
												CreateComponent(componentEntityId);
											}
										}
										bool manualAddFunction = false;
										luabridge::LuaRef manualAddFunctionRef = component["manualAddFunction"];
										if (!manualAddFunctionRef.isNil()) {
											manualAddFunction = manualAddFunctionRef.cast().value();
											if (manualAddFunction) {
												CreateComponent(componentEntityId);
											}
										}
										bool manualParseFunction = false;
										luabridge::LuaRef manualParseFunctionRef = component["manualParseFunction"];
										if (!manualParseFunctionRef.isNil()) {
											manualParseFunction = manualParseFunctionRef.cast().value();
											if (manualParseFunction) {
												CreateComponent(componentEntityId);
											}
										}
										bool manualSerializeFunction = false;
										luabridge::LuaRef manualSerializeFunctionRef = component["manualSerializeFunction"];
										if (!manualSerializeFunctionRef.isNil()) {
											manualSerializeFunction = manualSerializeFunctionRef.cast().value();
											if (manualSerializeFunction) {
												CreateComponent(componentEntityId);
											}
										}

										luabridge::LuaRef fields = component["fields"];


										if (!fields.isNil()) {
											std::vector parsedFieldsEntityIds;
											std::vector<std::pair> tablesNames;
											for (luabridge::Iterator it(fields); !it.isNil(); ++it) {
												luabridge::LuaRef field = it.value();

												ECS2::Entity::Id fieldEntityId = CreateEntity();
												CreateComponent(fieldEntityId);
												CreateComponent(fieldEntityId, field["type"].cast().value());
												CreateComponent(fieldEntityId, field["name"].cast().value());

												if (!field["defaultValue"].isNil()) {
													CreateComponent(fieldEntityId, field["defaultValue"].cast().value());
												}

												if (!field["alignment"].isNil()) {
													CreateComponent(fieldEntityId, field["alignment"].cast().value());
												}

												if (!field["copyable"].isNil()) {
													const bool copyable = field["copyable"].cast().value();
													if (copyable) {
														CreateComponent(fieldEntityId);
													}
												}
												else {
													CreateComponent(fieldEntityId);
												}

												parsedFieldsEntityIds.push_back(fieldEntityId);
											}
											CreateComponent(componentEntityId, parsedFieldsEntityIds);
										}
										if (!bindable) {
											if (manualBindFunction) {
												ASSERT_FAIL_MSG("Attempt to use \"manualBindFunction == true\" option when bindable == false.");
											}
										}

										return componentEntityId;
									}(table, name);

								return componentEntityId;
							}
							else if (name.ends_with("Constant")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								const ECS2::Entity::Id constantEntityId = ECS__FILE__TABLE__PARSE_CONSTANT(table, name.substr(0, name.rfind("Constant")));
								CreateComponent(constantEntityId, abstractionNameToOrderIndex[getFullName(fullName, name.substr(0, name.rfind("Constant")))]);
								return constantEntityId;
							}
							//deprecated
							else if (name.ends_with("Archetype")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								ECS2::Entity::Id archetypeEntityId = [&](luabridge::LuaRef archetype,
									const std::string& archetypeName) {

										ECS2::Entity::Id archetypeEntityId = CreateEntity();
										CreateComponent(archetypeEntityId);
										CreateComponent(archetypeEntityId);
										luabridge::LuaRef components = archetype["components"];
										CreateComponent(archetypeEntityId, archetypeName.substr(0, archetypeName.rfind("Archetype")));
										CreateComponent(archetypeEntityId, abstractionNameToOrderIndex[getFullName(fullName, archetypeName.substr(0, archetypeName.rfind("Archetype")))]);
										if (!components.isNil()) {
											std::vector archetypeComponents;
											for (luabridge::Iterator itJ(components); !itJ.isNil(); ++itJ) {
												luabridge::LuaRef componentRef = itJ.value();
												archetypeComponents.push_back({ componentRef.cast().value() });
											}
											CreateComponent(
												archetypeEntityId,
												std::vector{ ECS2::Entity::Id::invalid_, archetypeComponents.size() },
												archetypeComponents);
										}

										luabridge::LuaRef archetypes = archetype["archetypes"];

										if (!archetypes.isNil()) {
											std::vector archetypeRefArchetypes;
											for (luabridge::Iterator itJ(archetypes); !itJ.isNil(); ++itJ) {
												luabridge::LuaRef archetypeRef = itJ.value();
												archetypeRefArchetypes.push_back(
													{
														archetypeRef.cast().value()
													});
											}
											CreateComponent(
												archetypeEntityId,
												std::vector{ ECS2::Entity::Id::invalid_, archetypeRefArchetypes.size() },
												archetypeRefArchetypes);
										}
										return archetypeEntityId;

									}(table, name);

								return archetypeEntityId;
							}
							else if (name.ends_with("Bundle")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								ECS2::Entity::Id archetypeEntityId = [&](luabridge::LuaRef archetype,
									const std::string& archetypeName) {

										ECS2::Entity::Id archetypeEntityId = CreateEntity();
										CreateComponent(archetypeEntityId);
										CreateComponent(archetypeEntityId);
										luabridge::LuaRef components = archetype["components"];
										CreateComponent(archetypeEntityId, archetypeName.substr(0, archetypeName.rfind("Bundle")));
										CreateComponent(archetypeEntityId, abstractionNameToOrderIndex[getFullName(fullName, archetypeName.substr(0, archetypeName.rfind("Bundle")))]);
										if (!components.isNil()) {
											std::vector archetypeComponents;
											for (luabridge::Iterator itJ(components); !itJ.isNil(); ++itJ) {
												luabridge::LuaRef componentRef = itJ.value();
												archetypeComponents.push_back({ componentRef.cast().value() });
											}
											CreateComponent(
												archetypeEntityId,
												std::vector{ ECS2::Entity::Id::invalid_, archetypeComponents.size() },
												archetypeComponents);
										}

										luabridge::LuaRef archetypes = archetype["bundles"];

										if (!archetypes.isNil()) {
											std::vector archetypeRefArchetypes;
											for (luabridge::Iterator itJ(archetypes); !itJ.isNil(); ++itJ) {
												luabridge::LuaRef archetypeRef = itJ.value();
												archetypeRefArchetypes.push_back(
													{
														archetypeRef.cast().value()
													});
											}
											CreateComponent(
												archetypeEntityId,
												std::vector{ ECS2::Entity::Id::invalid_, archetypeRefArchetypes.size() },
												archetypeRefArchetypes);
										}
										return archetypeEntityId;

									}(table, name);

								return archetypeEntityId;
							}
							else if (name.ends_with("System")) {
								ASSERT_FMSG(std::isupper(name[0]), "Table name symbol must be uppercase.");
								ECS2::Entity::Id systemEntityId = [&](
									luabridge::LuaRef system,
									const std::string& systemName) {

										ECS2::Entity::Id systemEntityId = this->CreateEntity();

										CreateComponent(systemEntityId);
										CreateComponent(systemEntityId);
										CreateComponent(systemEntityId, systemName.substr(0, systemName.rfind("System")));
										if ("CreateLuaContext" == systemName.substr(0, systemName.rfind("System"))) {
											Common::BreakPointLine();
										}

										const std::string systemFullName = getFullName(fullName, systemName.substr(0, systemName.rfind("System")));
										CreateComponent(systemEntityId, abstractionNameToOrderIndex[systemFullName]);

										bool disableSystem = false;
										if (system["disable"].cast().value()) {
											disableSystem = true;

										}

										if (!system["type"].isNil()) {
											std::string typeStr = system["type"].cast().value();
											ASSERT(typeStr == "Initialize" || typeStr == "FrameToFrame");
											CreateComponent(systemEntityId, typeStr);
										}
										else {
											CreateComponent(systemEntityId, "FrameToFrame");
										}

										if (!system["tags"].isNil()) {
											luabridge::LuaRef tagsRef = system["tags"];
											std::vector tags;
											for (luabridge::Iterator it(tagsRef); !it.isNil(); ++it) {
												luabridge::LuaRef tagRef = it.value();
												tags.push_back(tagRef.cast().value());
											}

											if (!disableSystem/*optimization*/ && ECS::File::Table::Tags::SystemMatchesAny(tags, disableTags)) {
												disableSystem = true;
											}

											CreateComponent(systemEntityId, tags);

										}



										if (!system["thread"].isNil()) {
											std::string typeStr = system["thread"].cast().value();
											ASSERT(typeStr == "Main" || typeStr == "Child");
											CreateComponent(systemEntityId, typeStr);
										}
										else {
											CreateComponent(systemEntityId, "Child");
										}

										if (disableSystem) {
											LOG_INFO("", "System {} disabled.", systemFullName);
											CreateComponent(systemEntityId);
										}

										//Parse Call Order.
										[&](luabridge::LuaRef luaRef) {
											luabridge::LuaRef callOrderRef = luaRef["callOrder"];
											if (!callOrderRef.isNil()) {

												ECS2::Entity::Id callOrderEntityId = CreateEntity();

												//Parse runAfter
												[&](luabridge::LuaRef systemRef) {
													std::vector runAfterSystems;
													luabridge::LuaRef runAfterRef = systemRef["runAfter"];
													if (!runAfterRef.isNil()) {
														if (runAfterRef.isTable()) {
															for (luabridge::Iterator it(runAfterRef); !it.isNil(); ++it) {
																luabridge::LuaRef runAfterSystemRef = it.value();
																runAfterSystems.push_back({ ECS2::Entity::Id::invalid_, runAfterSystemRef.cast().value() });
															}
														}
														else {
															runAfterSystems.push_back({ ECS2::Entity::Id::invalid_, runAfterRef.cast().value() });
														}
														for (const auto& runAfterSystemInfo : runAfterSystems) {
															ASSERT(runAfterSystemInfo.name_ != "");
														}
														CreateComponent(callOrderEntityId, runAfterSystems);
													}
													else {
														CreateComponent(
															callOrderEntityId,
															std::vector{});
													}
													}(callOrderRef);

												//Parse runBefore
												[&](luabridge::LuaRef systemRef) {
													std::vector runBeforeSystems;
													luabridge::LuaRef runBeforeRef = systemRef["runBefore"];
													if (!runBeforeRef.isNil()) {
														if (runBeforeRef.isTable()) {
															for (luabridge::Iterator it(runBeforeRef); !it.isNil(); ++it) {
																luabridge::LuaRef runAfterSystemRef = it.value();
																runBeforeSystems.push_back({ ECS2::Entity::Id::invalid_, runAfterSystemRef.cast().value() });
															}
														}
														else {
															runBeforeSystems.push_back({ ECS2::Entity::Id::invalid_,runBeforeRef.cast().value() });
														}
														CreateComponent(callOrderEntityId, runBeforeSystems);
													}
													else {
														CreateComponent(
															callOrderEntityId,
															std::vector{});
													}

													}(callOrderRef);

												CreateComponent(systemEntityId, callOrderEntityId);
											}
											else {
												//Create empty call order.
												ECS2::Entity::Id callOrderEntityId = CreateEntity();
												CreateComponent(callOrderEntityId);
												CreateComponent(callOrderEntityId, std::vector{});
												CreateComponent(callOrderEntityId, std::vector{});
												CreateComponent(systemEntityId, callOrderEntityId);
											}
											}(system);

										luabridge::LuaRef updateMethodRef = system["updateMethod"];
										if (!updateMethodRef.isNil()) {

											//Parse UpdateMethod.
											[&](luabridge::LuaRef luaRef) {

												ECS2::Entity::Id updateMethodEntityId = CreateEntity();

												//Parse Accessing Entities.
												[&](luabridge::LuaRef systemRef) {
													//Access entities by id.
													luabridge::LuaRef accessingEntities = systemRef["accessingEntities"];

													if (!accessingEntities.isNil()) {
														std::vector accessingEntityIds;
														for (luabridge::Iterator it(accessingEntities); !it.isNil(); ++it) {

															ECS2::Entity::Id accessEntityId = CreateEntity();
															accessingEntityIds.push_back(accessEntityId);
															CreateComponent(accessEntityId);
															std::string archetype;
															luabridge::LuaRef toAccess = it.value();
															luabridge::LuaRef accessingComponentsRef = toAccess["accessingComponents"];

															if (systemName == "ProcessLoadResourceRequestSystem") {
																Common::BreakPointLine();
															}

															//Parse accessingComponents
															if (!accessingComponentsRef.isNil()) {
																std::vector accessesComponents;
																for (luabridge::Iterator itJ(accessingComponentsRef); !itJ.isNil(); ++itJ) {
																	luabridge::LuaRef accessingComponentRef = itJ.value();

																	accessesComponents.push_back({
																		accessingComponentRef.cast().value(),
																		false
																		});
																	ASSERT_FMSG(std::isupper(accessesComponents.back().name_[0]), "");
																}
																if (!accessesComponents.empty()) {
																	CreateComponent(
																		accessEntityId,
																		accessesComponents);
																}
															}

															//Parse archetype
															luabridge::LuaRef archetypeRef = toAccess["archetype"];
															if (!archetypeRef.isNil()) {
																archetype = archetypeRef.cast().value();
																CreateComponent(
																	accessEntityId,
																	ECS2::Entity::Id::invalid_,
																	archetype
																);
															}

															ASSERT_MSG(
																(!accessingComponentsRef.isNil() && archetypeRef.isNil()) ||
																(accessingComponentsRef.isNil() && !archetype.empty()),
																"Access entity can't access archetype components and raw components at one time.");

															//Parse createsComponents
															luabridge::LuaRef createsComponentsRef = toAccess["createsComponents"];
															if (!createsComponentsRef.isNil()) {
																std::vector createsComponents;
																for (luabridge::Iterator itJ(createsComponentsRef); !itJ.isNil(); ++itJ) {
																	luabridge::LuaRef createsComponentRef = itJ.value();
																	createsComponents.push_back({ createsComponentRef.cast().value() });
																	ASSERT_FMSG(std::isupper(createsComponents.back()[0]), "");
																}
																if (!createsComponents.empty()) {
																	CreateComponent(
																		accessEntityId,
																		createsComponents);
																}
															}

															//Parse removesComponents
															luabridge::LuaRef removesComponentsRef = toAccess["removesComponents"];
															if (!removesComponentsRef.isNil()) {
																std::vector removesComponents;
																for (luabridge::Iterator itJ(removesComponentsRef); !itJ.isNil(); ++itJ) {
																	luabridge::LuaRef removesComponentRef = itJ.value();
																	removesComponents.push_back(removesComponentRef.cast().value());
																	ASSERT_FMSG(std::isupper(removesComponents.back()[0]), "");
																}
																if (!removesComponents.empty()) {
																	CreateComponent(
																		accessEntityId,
																		removesComponents);
																}
															}

														}
														CreateComponent(
															updateMethodEntityId,
															accessingEntityIds);
													}

													}(luaRef);

												//Parse Processing Entities.
												[&](luabridge::LuaRef luaRef) {

													luabridge::LuaRef entities = luaRef["processesEntities"];
													if (entities.isNil()) {
														return;
													}
													std::vector proccessesEntities;
													for (luabridge::Iterator it(entities); !it.isNil(); ++it) {
														luabridge::LuaRef entity = it.value();

														ECS2::Entity::Id proccessEntityId = CreateEntity();
														CreateComponent(proccessEntityId);

														luabridge::LuaRef processesAllCombinations = entity["processesAllCombinations"];

														const bool processAllCombinations = processesAllCombinations.cast().value();

														if (processAllCombinations) {
															CreateComponent(proccessEntityId);
														}
														//Parse processesComponents.
														[&](luabridge::LuaRef luaRef) {

															luabridge::LuaRef entityIncludes = luaRef["processesComponents"];

															if (entityIncludes.isNil()) {
																return;
															}

															std::vector processesComponents;

															for (luabridge::Iterator it(entityIncludes); !it.isNil(); ++it) {
																ECS::File::Table::System::UpdateMethod::Process::Entity::ComponentInfo componentInfo{ "", true };
																luabridge::LuaRef include = it.value();
																if (!include.isNil()) {

																	luabridge::LuaRef includeName = include["name"];
																	if (!includeName.isNil()) {
																		componentInfo.name_ = includeName.cast().value();
																	}
																	else {
																		componentInfo.name_ = include.cast().value();
																	}
																	luabridge::LuaRef isIncludeReadonly = include["readonly"];
																	if (!isIncludeReadonly.isNil()) {
																		componentInfo.readonly_ = isIncludeReadonly.cast().value();
																	}

																}

																processesComponents.push_back(componentInfo);
															}
															CreateComponent(
																proccessEntityId,
																processesComponents);

															}(entity);

														//ASSERT_FMSG(
														//	(luaRef["processesComponents"].isNil() && !processesAllCombinations.isNil())
														//	|| (!luaRef["processesComponents"].isNil() && processesAllCombinations.isNil()),
														//	"System description error."
														//	" Using processesAllCombinations && processesComponents together is incorrect.");

														//Parse excludes.
														[&](luabridge::LuaRef luaRef) {

															luabridge::LuaRef entityExcludes = luaRef["excludes"];
															std::vector parsedEntityExcludes;
															if (!entityExcludes.isNil()) {
																for (luabridge::Iterator it(entityExcludes); !it.isNil(); ++it) {
																	luabridge::LuaRef exclude = it.value();
																	parsedEntityExcludes.push_back({ exclude.cast().value() });

																	//ASSERT_FMSG(std::isupper(parsedEntityExcludes.back().name_[0]), "");

																}
															}
															CreateComponent(
																proccessEntityId,
																parsedEntityExcludes);

															}(entity);

														//Parse removes.
														[&](luabridge::LuaRef systemOrEntityRef) {

															luabridge::LuaRef entityRemoves = systemOrEntityRef["removesComponents"];

															std::vector parsedEntityRemoves;
															if (!entityRemoves.isNil()) {
																for (luabridge::Iterator it(entityRemoves); !it.isNil(); ++it) {
																	luabridge::LuaRef toRemove = it.value();
																	parsedEntityRemoves.push_back(toRemove.cast().value());
																}
															}
															CreateComponent(
																proccessEntityId,
																parsedEntityRemoves);

															}(entity);

														[&](luabridge::LuaRef luaRef) {

															luabridge::LuaRef entityExcludes = luaRef["accessingComponents"];

															std::vector parsedEntityAccessing;
															if (!entityExcludes.isNil()) {
																for (luabridge::Iterator it(entityExcludes); !it.isNil(); ++it) {
																	luabridge::LuaRef exclude = it.value();
																	parsedEntityAccessing.push_back(exclude.cast().value());
																}
															}
															CreateComponent(
																proccessEntityId,
																parsedEntityAccessing);

															}(entity);

														proccessesEntities.push_back(proccessEntityId);

													}
													CreateComponent(
														updateMethodEntityId, proccessesEntities);

													}(luaRef);

												//Parse Creates Entities.
												[&](luabridge::LuaRef luaRef) {

													std::vector createsEntities_;

													luabridge::LuaRef createsEntity = luaRef["createsEntities"];
													if (!createsEntity.isNil()) {
														for (luabridge::Iterator it(createsEntity); !it.isNil(); ++it) {

															ECS2::Entity::Id createEntityEntityId = CreateEntity();

															//Parse Creates Components.
															[&](luabridge::LuaRef luaRef) {

																luabridge::LuaRef entityCreates = luaRef["createsComponents"];

																std::vector parsedEntityCreates;
																if (!entityCreates.isNil()) {
																	for (luabridge::Iterator it(entityCreates); !it.isNil(); ++it) {
																		luabridge::LuaRef toCreate = it.value();
																		parsedEntityCreates.push_back(toCreate.cast().value());
																	}
																}

																CreateComponent(
																	createEntityEntityId,
																	parsedEntityCreates);

																}(it.value());

															luabridge::LuaRef archetypeRef = it.value()["archetype"];
															if (!archetypeRef.isNil()) {

																CreateComponent(
																	createEntityEntityId,
																	ECS2::Entity::Id::invalid_,
																	archetypeRef.cast().value()
																);
															}

															ASSERT_MSG(
																(luaRef["createsComponents"].isNil() && !archetypeRef.isNil()) ||
																(!luaRef["createsComponents"].isNil() && archetypeRef.isNil()),
																"Access entity can't creates archetype components and raw components at one time.");

															createsEntities_.push_back(createEntityEntityId);
														}
													}
													return createsEntities_;
													};
												CreateComponent(systemEntityId, updateMethodEntityId);
												}(updateMethodRef);

										}

										return systemEntityId;
									}(table, name);
								return systemEntityId;
							}



							return ECS2::Entity::Id::invalid_;
					};

				for (auto it = luabridge::pairs(ecsFile).begin(); !it.isNil(); ++it) {

					luabridge::LuaRef key = it.key();
					luabridge::LuaRef value = it.value();

					//Key must be string.
					if (!key.isString()) {
						continue;
					}

					//Value must be a table(description of component, system...) or a string(component alias)
					if (!(value.isTable() || value.isString())) {
						continue;
					}

					const std::string keyString = key.tostring();
					luabridge::LuaRef table = key;

					std::vector fullName;



					const ECS2::Entity::Id parsedTableEntityId = processTable(keyString, ecsFile[key.tostring()], fullName);

					if (parsedTableEntityId.IsValid()) {

						::Lua::Script projectScript{ luaScript0->text_ };

						::Lua::Context projectContext;
						projectContext.LoadScript(projectScript);
						luabridge::LuaRef ecsTable = luabridge::getGlobal(projectContext.state_, "ECS");

						//ecsTable.

						if (ecsTable.isTable() && !ecsTable["GlobalNamespace"].isNil()) {
							CreateComponent(parsedTableEntityId, entity1id);
							ECS2::Entity::Id namespaceTableEntityId = CreateEntity();
							CreateComponent(namespaceTableEntityId);
							CreateComponent(namespaceTableEntityId);
							CreateComponent(namespaceTableEntityId, ecsTable["GlobalNamespace"].cast().value());
							CreateComponent(
								namespaceTableEntityId,
								std::vector{ parsedTableEntityId });

							CreateComponent(parsedTableEntityId, namespaceTableEntityId);

							CreateComponent(namespaceTableEntityId, entity1id);
							parsedTables.push_back(namespaceTableEntityId);
						}
						else {
							CreateComponent(parsedTableEntityId, entity1id);
							parsedTables.push_back(parsedTableEntityId);
						}

					}

					//Separate namespace tables:
					//namespace {
					//	struct{}
					//	struct {}
					//}
					//to:
					//namespace {
					//struct {}
					// }
					// namespace {
					// struct {}
					// }
					//std::vector separatedTables;

					//parsedTable->ForEachChildlessTable([&](ParsedTablePtr childlessTable) {

					//	ASSERT_FMSG(!childlessTable->HasChilds(), "");

					//	auto parentTables = childlessTable->GetParentTables();

					//	std::vector<std::shared_ptr> clonedTables;
					//	std::ranges::for_each(parentTables, [&](std::shared_ptr parentTable) {
					//		auto clonedParentTable = parentTable->Clone();
					//		clonedParentTable->childTables_.clear();
					//		clonedParentTable->parentTable_ = nullptr;
					//		clonedTables.push_back(clonedParentTable);

					//		});
					//	auto clonedChildlessTable = childlessTable->Clone();
					//	clonedChildlessTable->childTables_.clear();
					//	clonedChildlessTable->parentTable_ = nullptr;

					//	clonedTables.push_back(clonedChildlessTable);

					//	{
					//		const Common::Index lastTableIndex = clonedTables.size() - 1;
					//		for (Common::Index i = 0; i < clonedTables.size(); i++) {
					//			auto clonedTable = clonedTables[i];
					//			const Common::Index nextTableIndex = i + 1;
					//			if (nextTableIndex <= lastTableIndex) {
					//				auto nextClonedTable = clonedTables[nextTableIndex];
					//				nextClonedTable->parentTable_ = clonedTable;
					//				clonedTable->childTables_.push_back(nextClonedTable);
					//			}
					//		}
					//	}

					//	separatedTables.push_back(clonedTables[0]);

					//	return true;
					//	});

					////If there are no separated tables it means that parsed table doesnt have childs.
					//if (separatedTables.empty()) {
					//	separatedTables.push_back(parsedTable);
					//}

					//for (auto separatedTable : separatedTables) {
					//	parsedTables.push_back(separatedTable);
					//}
				}

			}
			CreateComponent(entity1id, parsedTables);
		}


		void ValidateCallOrderDependecies::Update(
			ECS2::Entity::Id entity0id,
			const ECS::File::Table::Tag* eCS__File__Table__Tag0,
			const ECS::File::Table::System::Tag* eCS__File__Table__System__Tag0) {

			if (IsComponentExist(entity0id)) {

			}

			ECS2::Entity::Id callOrderEntityId = GetComponent(entity0id)->id_;

			std::string systemName = File::Table::GetFullName(this, entity0id, "::", false);

			auto& runAfterSystems = GetComponent(callOrderEntityId)->systems_;
			for (auto& systemInfo : runAfterSystems) {
				ECS2::Entity::Id runAfterSystemEntityId = File::Table::GetTableEntityIdByNameOrInvalidId(
					this,
					entity0id,
					systemInfo.name_);
				systemInfo.id_ = runAfterSystemEntityId;

			}

			auto& runBeforeSystems = GetComponent(callOrderEntityId)->systems_;
			for (auto& systemInfo : runBeforeSystems) {
				ECS2::Entity::Id runBeforeSystemEntityId = File::Table::GetTableEntityIdByNameOrInvalidId(
					this,
					entity0id,
					systemInfo.name_);
				systemInfo.id_ = runBeforeSystemEntityId;

			}
		}

		void CreateCallOrderAdditionalDependencies::Update(
			ECS2::Entity::Id entity0id, const ECS::Project::Tag* eCS__Project__Tag0,
			const ECS::Project::Path* eCS__Project__Path0, const Behaviour::LuaScript* luaScript0) {

			const Common::Size allSystemsNumber = world_->GetEntitiesNumber();
			ASSERT_FMSG(allSystemsNumber > 0, "No systems to process. Check .ecs file or project setup.");
			const auto systemComponents = world_->GetComponents();

			//Add dependencies between systems that has conflicts.
			std::vector systemsOrder;
			std::unordered_map orederedSystemIdToIndex;
			std::unordered_map inDegree;
			std::queue rootSystems;

			//Get REGULAR ROOT systems 
			for (Common::Index i = 0; i < allSystemsNumber; i++) {

				ECS2::Entity::Id systemEntityId = *(std::get(systemComponents) + i);
				const std::string systemName = File::Table::GetFullName(this, systemEntityId, "::", false);

				if (systemName == "PacketManager::GetRequiredPackets") {
					Common::BreakPointLine();
				}

				//Skip Initialize systems.
				if (IsComponentExist(systemEntityId)) {
					const auto systemType = *(std::get(systemComponents) + i);
					if (systemType.type_ == "Initialize") {
						continue;
					}
				}

				//Skip disabled systems.
				if (IsComponentExist(systemEntityId)) {
					LOG_INFO("", "Skiped disabled system {}", systemName);
					continue;
				}

				//Add system to root systems if there are no RunAfter systems.
				ECS2::Entity::Id callOrderEntityId = (std::get(systemComponents) + i)->id_;
				if (callOrderEntityId.IsValid()) {
					if (IsComponentExist(callOrderEntityId)) {
						const ECS::File::Table::System::CallOrder::RunAfter* systemRunAfter = GetComponent(callOrderEntityId);
						inDegree[systemEntityId] = systemRunAfter->systems_.size();
						if (systemRunAfter->systems_.size() == 0) {
							rootSystems.push(systemEntityId);
						}
					}
					else {
						rootSystems.push(systemEntityId);
					}

				}
				else {
					rootSystems.push(systemEntityId);
				}

			}

			// 2. Алгоритм Кана
			while (!rootSystems.empty()) {
				ECS2::Entity::Id currentId = rootSystems.front();
				const std::string systemName = File::Table::GetFullName(this, currentId, "::", false);
				rootSystems.pop();
				systemsOrder.push_back(currentId);
				orederedSystemIdToIndex[currentId] = systemsOrder.size() - 1;

				// Уменьшаем inDegree для всех соседей
				ECS2::Entity::Id callOrderEntityId = GetComponent(currentId)->id_;

				const auto* runBefore = GetComponent(callOrderEntityId);
				for (const auto& runBeforeSystemInfo : runBefore->systems_) {
					const ECS2::Entity::Id runBeforeSystemEntityId = runBeforeSystemInfo.id_;
					//Skip disabled systems.
					if (runBeforeSystemEntityId.IsInvalid()) {
						continue;
					}
					auto it = inDegree.find(runBeforeSystemEntityId);
					if (it != inDegree.end() && it->second > 0) {
						it->second--;
						if (it->second == 0) {
							rootSystems.push(runBeforeSystemEntityId);
						}
					}
				}
			}



			std::unordered_map<ECS2::Entity::Id, std::unordered_set, ECS2::Entity::Id::Hash>  componentToSystems;
			std::unordered_set  componentUsedByWriteSystem;

			for (ECS2::Entity::Id systemEntityId : systemsOrder) {
				ECS2::ComponentsFilter systemCF = GetComponentsFilter(systemEntityId);

				ASSERT_FMSG(systemEntityId.IsValid(), "Invalid system entity id in systens order.");

				std::string systemName = File::Table::GetFullName(this, systemEntityId, "::", false);

				const auto writeComponents = File::Table::GetWriteComponentEntityIds(this, systemEntityId);
				const auto readComponents = File::Table::GetReadComponentEntityIds(this, systemEntityId);

				for (ECS2::Entity::Id writeComponent : writeComponents) {
					componentToSystems[writeComponent].insert(systemEntityId);
					componentUsedByWriteSystem.insert(writeComponent);
				}

				for (ECS2::Entity::Id readComponent : readComponents) {
					componentToSystems[readComponent].insert(systemEntityId);
				}
			}



			std::unordered_set systemsThatHasGroup;

			for (auto componentEntityId : componentUsedByWriteSystem) {
				if (componentToSystems.contains(componentEntityId)) {
					std::unordered_set& systems = componentToSystems[componentEntityId];
					systemsThatHasGroup.insert(systems.begin(), systems.end());
				}
			}

			std::vector componentsToRemove;
			//Remove grouos with no conflicts
			for (auto& [component, systems] : componentToSystems) {
				if (!componentUsedByWriteSystem.contains(component)) {
					componentsToRemove.push_back(component);
				}
			}
			for (auto componentToRemove : componentsToRemove) {
				componentToSystems.erase(componentToRemove);
			}


			//System to conflict systems set
			std::unordered_map<ECS2::Entity::Id, std::unordered_set, ECS2::Entity::Id::Hash> systemToDependenceSystems;

			for (auto& [component, systems] : componentToSystems) {
				for (auto sysA : systems) {
					for (auto sysB : systems) {
						if (sysA != sysB) {
							systemToDependenceSystems[sysA].insert(sysB);
						}
					}
				}
			}



			std::vector orderedMainThreadSystems;
			std::vector orderedChildThreadSystems;

			for (ECS2::Entity::Id systemEntityId : systemsOrder) {
				const std::string systemName = File::Table::GetFullName(this, systemEntityId, "::", false);
				if (IsComponentExist(systemEntityId)) {
					const std::string thread = GetComponent(systemEntityId)->thread_;
					if (thread == "Main") {
						orderedMainThreadSystems.push_back(systemEntityId);
					}
					else {
						orderedChildThreadSystems.push_back(systemEntityId);
					}
				}

				//Add additional dependencies
				if (systemToDependenceSystems.contains(systemEntityId)) {

					const auto& dependenceSystems = systemToDependenceSystems[systemEntityId];
					for (ECS2::Entity::Id dependenceSystem : dependenceSystems) {
						if (dependenceSystem == systemEntityId) {
							continue;
						}
						std::string name = File::Table::GetFullName(this, dependenceSystem, "::", false);

						Common::Index dependenceSystemIndex = orederedSystemIdToIndex[dependenceSystem];
						Common::Index currentSystemIndex = orederedSystemIdToIndex[systemEntityId];
						ASSERT(dependenceSystemIndex != currentSystemIndex);
						if (currentSystemIndex < dependenceSystemIndex) {
							File::Table::ECS__FILE__TABLE__SYSTEM__ADD_RUN_AFTER_SYSTEM(this, dependenceSystem, systemEntityId);
						}
						else {
							File::Table::ECS__FILE__TABLE__SYSTEM__ADD_RUN_BEFORE_SYSTEM(this, dependenceSystem, systemEntityId);

						}
					}

				}


			}

			//If System1 runs before System2 need to add System2 runs after System1
			for (Common::Index i = 0; i < allSystemsNumber; i++) {
				ECS2::Entity::Id systemEntityId = *(std::get(systemComponents) + i);
				/*if (IsComponentExist(systemEntityId)) {
					const auto systemType = *(std::get(systemComponents) + i);
					if (systemType.type_ == "Initialize") {
						continue;
					}
				}*/
				const std::string systemFullName = File::Table::GetFullName(this, systemEntityId, "::", false);

				if (systemFullName == "PacketManager::GetRequiredPackets") {
					Common::BreakPointLine();
				}
				if (systemFullName == "PacketManager::GetPacketsToDownload") {
					Common::BreakPointLine();
				}

				ECS2::Entity::Id callOrderEntityId = GetComponent(systemEntityId)->id_;

				//Create reverse dependences.
				auto dependenceRunAfterSystems = GetComponent(callOrderEntityId)->systems_;
				for (auto runAfterSystemName : dependenceRunAfterSystems) {
					ECS2::Entity::Id runAfterEntityId = File::Table::GetTableEntityIdByNameOrInvalidId(
						this,
						systemEntityId,
						runAfterSystemName.name_);

					if (runAfterEntityId.IsValid()) {
						File::Table::ECS__FILE__TABLE__SYSTEM__ADD_RUN_BEFORE_SYSTEM(this, runAfterEntityId, systemEntityId);
					}
				}
				auto dependenceRunBeforeSystems = GetComponent(callOrderEntityId)->systems_;
				for (auto runBeforeSystemName : dependenceRunBeforeSystems) {
					ECS2::Entity::Id runBeforeEntityId = File::Table::GetTableEntityIdByNameOrInvalidId(
						this,
						systemEntityId,
						runBeforeSystemName.name_);
					if (runBeforeEntityId.IsValid()) {
						File::Table::ECS__FILE__TABLE__SYSTEM__ADD_RUN_AFTER_SYSTEM(this, runBeforeEntityId, systemEntityId);
					}
				}
			}

			//std::vector runAfterSystems;
			//std::vector runBeforeSystems;

			//if (IsComponentExist(entity0id)) {
			//	ECS2::Entity::Id callOrderEntityId = GetComponent(entity0id)->id_;
			//	if (IsComponentExist(callOrderEntityId)) {
			//		auto& currentRunAfterSystems = GetComponent(callOrderEntityId)->systems_;
			//		for (auto& runAfterSystemInfo : runAfterSystems) {

			//			auto it = std::find_if(
			//				currentRunAfterSystems.begin(),
			//				currentRunAfterSystems.end(),
			//				[&](auto& afterSystem) {
			//					if (afterSystem.id_.IsInvalid()) {
			//						afterSystem.id_ = ECS__FILE__TABLE__GET_TABLE_ENTITY_ID_BY_NAME(
			//							ECS::File::Table::System::Tag,
			//							entity0id,
			//							afterSystem.name_);
			//					}
			//					return runAfterSystemInfo.id_ == afterSystem.id_;
			//				}
			//			);
			//			if (it == currentRunAfterSystems.end()) {
			//				currentRunAfterSystems.push_back(runAfterSystemInfo);
			//			}

			//		}
			//	}
			//	else {
			//		if (!runAfterSystems.empty()) {
			//			CreateComponent(callOrderEntityId, runAfterSystems);
			//		}
			//	}
			//	if (IsComponentExist(callOrderEntityId)) {
			//		auto& currentRunBeforeSystems = GetComponent(callOrderEntityId)->systems_;
			//		for (auto& runBeforeSystemInfo : runBeforeSystems) {
			//			auto it = std::find_if(
			//				currentRunBeforeSystems.begin(),
			//				currentRunBeforeSystems.end(),
			//				[&](auto& beforeSystem) {
			//					if (beforeSystem.id_.IsInvalid()) {
			//						beforeSystem.id_ = ECS__FILE__TABLE__GET_TABLE_ENTITY_ID_BY_NAME(
			//							ECS::File::Table::System::Tag,
			//							entity0id,
			//							beforeSystem.name_);
			//					}
			//					return runBeforeSystemInfo.id_ == beforeSystem.id_;
			//				}
			//			);
			//			if (it == currentRunBeforeSystems.end()) {
			//				currentRunBeforeSystems.push_back(runBeforeSystemInfo);
			//			}
			//		}
			//	}
			//	else {
			//		if (!runBeforeSystems.empty()) {
			//			CreateComponent(callOrderEntityId, runBeforeSystems);
			//		}
			//	}
			//}
			//else {
			//	if (!runAfterSystems.empty() || !runBeforeSystems.empty()) {
			//		ECS2::Entity::Id callOrderEntityId = CreateEntity();
			//		CreateComponent(callOrderEntityId);
			//		if (!runAfterSystems.empty()) {
