	template
	::std::string GetName(System* system, ECS2::Entity::Id tableEntityId, bool isUppercase) {
		ASSERT(system->template IsComponentExist(tableEntityId));
		ASSERT(system->template IsComponentExist(tableEntityId));
		::std::string tableName = system->template GetComponent(tableEntityId)->name_;
		if (isUppercase) {
			::std::transform(tableName.begin(), tableName.end(), tableName.begin(),
				[](unsigned char c) { return ::std::toupper(c); });
		}
		return tableName;
	}

