	template
	::std::string GetFullName(System* system, ECS2::Entity::Id tableEntityId, const char* delimiter, bool isUppercase) {
		::std::string tableName = GetName(system, tableEntityId, isUppercase);
		const ::std::string tableNamespace = GetFullNamespaceString(system, tableEntityId, delimiter, isUppercase);
		return tableNamespace + delimiter + tableName;
	}

#define ECS__FILE__TABLE__GET_ALL_COMPONENT_ENTITY_IDS()																			\
		[this]() {																													\
			const Common::Size allComponentsNumber = world_->GetEntitiesNumber();			\
			const auto componentComponents = GetComponents();								\
			const ECS2::Entity::Id* componentEntityIdsPtr = ::std::get(componentComponents);						\
			::std::vector componentEntityIds{ componentEntityIdsPtr, componentEntityIdsPtr + allComponentsNumber };	\
			return componentEntityIds;																								\
		}()

	template
	ECS2::Entity::Id GetTableEntityIdByNameOrInvalidId(System* system, ECS2::Entity::Id usageTableEntityId, const ::std::string& findingFullTableName) {
		BEGIN_PROFILE("ECS__FILE__TABLE__GET_TABLE_ENTITY_ID_BY_NAME");
		ASSERT(ECS::File::Table::IsValidName(findingFullTableName));
		::std::vector<::std::string> systemNamespaceNames = File::Table::GetSplitedNamespaceNames(system, usageTableEntityId);
		systemNamespaceNames.insert(systemNamespaceNames.begin(), "Root");
		::std::vector<::std::string> findingTableSplitedFullName = ECS::File::Table::SplitName(findingFullTableName);
		if (findingFullTableName.starts_with("::")) {
			findingTableSplitedFullName.insert(findingTableSplitedFullName.begin(), "Root");
		}
		const ::std::string findingTableName = findingTableSplitedFullName.back();
		::std::vector<::std::string> findingTableSplitedNamespaces = findingTableSplitedFullName;
		findingTableSplitedNamespaces.pop_back();
		::std::vector<::std::pair> applicants;
		system->world_->ForEachEntity([&](ECS2::Entity::Id tableEntityId) {
			const ECS2::ComponentsFilter tableCF = system->GetComponentsFilter(tableEntityId);
			if (!tableCF.IsSet()) {
				return;
			}
			const ::std::string tableName = system->template GetComponent(tableEntityId)->name_;
			if (tableName != findingTableName) {
				return;
			}
			::std::vector<::std::string> tableSplitedNamespaces = File::Table::GetSplitedNamespaceNames(system, tableEntityId);
			tableSplitedNamespaces.insert(tableSplitedNamespaces.begin(), "Root");
			bool isFindingAndCurrentTablesHasCommonNamespace = [](
				const ::std::vector<::std::string>& first,
				const ::std::vector<::std::string>& second) {
					if (second.empty()) {
						return true;
					}
					for (auto rIt = first.rbegin(); rIt != first.rend(); ++rIt) {
						if (*rIt == *second.begin()) {
							const Common::UInt64 offset = ::std::distance(rIt, first.rend()) - 1;
							if (first.size() - offset != second.size()) {
								return false;
							}
							for (Common::Index j = offset; j < first.size(); j++) {
								if (first[j] != second[j - offset]) {
									return false;
								}
							}
							return true;
						}
					}
					return false;
				}(tableSplitedNamespaces, findingTableSplitedNamespaces);
			if (!isFindingAndCurrentTablesHasCommonNamespace) {
				return;
			}
			for (auto rIt = systemNamespaceNames.rbegin(); rIt != systemNamespaceNames.rend(); ++rIt) {
				if (*rIt == tableSplitedNamespaces.front()) {

					applicants.push_back({ ::std::abs(::std::distance(rIt, systemNamespaceNames.rbegin())), tableEntityId });
				}
			}
			});
		if (applicants.empty()) {
			return ECS2::Entity::Id::invalid_;
		}
		::std::sort(applicants.begin(), applicants.end(),
			[](::std::pair& first, ::std::pair& second) {
				return	first.first < second.first;
			});
		END_PROFILE();
		return applicants.front().second;
	}

	template
	ECS2::Entity::Id GetTableEntityIdByName(System* system, ECS2::Entity::Id usageTableEntityId, const ::std::string& findingFullTableName) {
		const ECS2::Entity::Id tableEntityId = File::Table::GetTableEntityIdByNameOrInvalidId(system, usageTableEntityId, findingFullTableName);
		ASSERT_FMSG(
			tableEntityId.IsValid(),
			"Can't find {} in context {}.", findingFullTableName, GetFullName(system, usageTableEntityId, "::", false));
		return tableEntityId;

	}

	template
	ECS2::Entity::Id GetTableFileEntity(System* system, ECS2::Entity::Id tableEntityId) {
		return system->template GetComponent(tableEntityId)->id_;
	}

	template
	::std::filesystem::path GetFileIncludePath(System* system, ECS2::Entity::Id fileEntityId, ::std::filesystem::path projectFileFullPath, ::std::string extensionStr) {
		auto projectFilePathIt = projectFileFullPath.begin();
		::std::filesystem::path ecsFilePath = system->template GetComponent(fileEntityId)->path_;
		if (ecsFilePath.is_absolute()) {
			::std::filesystem::path relative = ecsFilePath.lexically_relative(projectFileFullPath);
			return relative.parent_path() / ("auto_" + relative.stem().string() + extensionStr);
		}
		auto hppFilePathIt = ecsFilePath.begin();
		while (*projectFilePathIt == *hppFilePathIt) {
			++projectFilePathIt;
			++hppFilePathIt;
		}
		::std::filesystem::path hppFileRelativePath;
		ASSERT(*hppFilePathIt == "Sources");
		++hppFilePathIt;
		while (hppFilePathIt != ecsFilePath.end()) {
			hppFileRelativePath /= *hppFilePathIt;
			++hppFilePathIt;
		}
		hppFileRelativePath = hppFileRelativePath.parent_path() / ("auto_" + hppFileRelativePath.stem().string() + extensionStr);
		return hppFileRelativePath;
	}

	template
	::std::vector GetWriteComponentEntityIds(System* system, ECS2::Entity::Id systemEntityId) {
		ASSERT(system->template IsComponentExist(systemEntityId));
		::std::vector writeComponents;
		if (system->template IsComponentExist(systemEntityId)) {
			ECS2::Entity::Id updateMethodEntityId
				= system->template GetComponent(systemEntityId)->id_;
			ECS2::ComponentsFilter updateMethodCF = system->GetComponentsFilter(updateMethodEntityId);
			if (system->template IsComponentExist(updateMethodEntityId)) {
				::std::vector processesEntities
					= system->template GetComponent(updateMethodEntityId)->entityIds_;
				for (ECS2::Entity::Id processesEntity : processesEntities) {
					const bool allCombinations = system->template IsComponentExist(processesEntity);
					if (allCombinations) continue;
					const auto& processComponentInfos = system->template GetComponent(processesEntity)->componentInfos_;
					for (auto& processComponentInfo : processComponentInfos) {
						ECS2::Entity::Id componentEntityId = GetTableEntityIdByName(
							system,
							systemEntityId,
							processComponentInfo.name_);
						if (!processComponentInfo.readonly_) {
							writeComponents.push_back(componentEntityId);
						}
					}
				}
			}
			if (system->template IsComponentExist(updateMethodEntityId)) {
				::std::vector accessesEntities
					= system->template GetComponent(updateMethodEntityId)->entityIds_;
				for (ECS2::Entity::Id accessEntity : accessesEntities) {
					if (system->template IsComponentExist(accessEntity)) {
						const auto& accessComponentInfos = system->template GetComponent(accessEntity)->components_;
						for (auto& accessComponentInfo : accessComponentInfos) {
							ECS2::Entity::Id componentEntityId = GetTableEntityIdByName(
								system,
								systemEntityId,
								accessComponentInfo.name_);
							if (!accessComponentInfo.readonly_) {
								writeComponents.push_back(componentEntityId);
							}
						}
					}
					//archetype
					if (system->template IsComponentExist(accessEntity)) {
						const std::string archetypeLocalName = system->template  GetComponent(accessEntity)->name_;
						ECS2::Entity::Id archetypeEntityId = File::Table::GetTableEntityIdByName(system, systemEntityId, archetypeLocalName);
						//TODO: Get archetype components

					}
				}
			}
		}
		return writeComponents;
	}

	template
	::std::vector GetReadComponentEntityIds(System* system, ECS2::Entity::Id systemEntityId) {
		ASSERT(system->template IsComponentExist(systemEntityId));
		::std::vector readComponents;
		if (system->template IsComponentExist(systemEntityId)) {
			ECS2::Entity::Id updateMethodEntityId
				= system->template GetComponent(systemEntityId)->id_;
			ECS2::ComponentsFilter updateMethodCF = system->GetComponentsFilter(updateMethodEntityId);
			if (system->template IsComponentExist(updateMethodEntityId)) {
				::std::vector processesEntities
					= system->template GetComponent(updateMethodEntityId)->entityIds_;
				for (ECS2::Entity::Id processesEntity : processesEntities) {
					const bool allCombinations = system->template IsComponentExist(processesEntity);
					if (allCombinations) continue;


					if (system->template IsComponentExist(processesEntity)) {
						const auto* archetype = system->template GetComponent(processesEntity);

					}
					const auto& processComponentInfos = system->template GetComponent(processesEntity)->componentInfos_;
					for (auto& processComponentInfo : processComponentInfos) {
						ECS2::Entity::Id componentEntityId = GetTableEntityIdByName(
							system,
							systemEntityId,
							processComponentInfo.name_);
						if (processComponentInfo.readonly_) {
							readComponents.push_back(componentEntityId);
						}
					}
				}
			}
			if (system->template IsComponentExist(updateMethodEntityId)) {
				::std::vector accessesEntities
					= system->template GetComponent(updateMethodEntityId)->entityIds_;
				for (ECS2::Entity::Id accessEntity : accessesEntities) {
					if (system->template IsComponentExist(accessEntity)) {
						const auto& accessComponentInfos = system->template GetComponent(accessEntity)->components_;
						for (auto& accessComponentInfo : accessComponentInfos) {
							ECS2::Entity::Id componentEntityId = File::Table::GetTableEntityIdByName(
								system,
								systemEntityId,
								accessComponentInfo.name_);
							if (accessComponentInfo.readonly_) {
								readComponents.push_back(componentEntityId);
							}
						}
					}
				}
			}
		}
		return readComponents;
	}

	template
	std::vector GetTableParents(System* system, ECS2::Entity::Id tableEntityId) {
		ASSERT(system->IsComponentExist(tableEntityId));
		if (!system->template IsComponentExist(tableEntityId)) {
			return {};
		}
		else {
			ECS2::Entity::Id parentTableEntityId = system->template GetComponent(tableEntityId)->id_;
			std::vector parentTables;
			std::function processParent =
				[system, &parentTables, &processParent]
				(ECS2::Entity::Id parentTableEntityId) {
				if (system->template IsComponentExist(parentTableEntityId)) {
					processParent(system->template GetComponent(parentTableEntityId)->id_);
				}
				parentTables.push_back(parentTableEntityId);
				};
			processParent(parentTableEntityId);
			return parentTables;
		}
	}


	template
	::std::vector GetComponentsEntityIds(System* system, ECS2::Entity::Id systemEntityId) {
		const auto readComponents = GetReadComponentEntityIds(system, systemEntityId);
		const auto writeComponents = GetWriteComponentEntityIds(system, systemEntityId);
		::std::vector allComponents = readComponents;
		allComponents.insert(allComponents.end(), writeComponents.begin(), writeComponents.end());
		::std::sort(allComponents.begin(), allComponents.end());
		allComponents.erase(::std::unique(allComponents.begin(), allComponents.end()), allComponents.end());
		return allComponents;
	}

#define ECS__FILE__TABLE__SYSTEM__HAS_RUN_BEFORE_SYSTEMS(systemE)																									\
	[this](ECS2::Entity::Id systemEntityId) -> bool {																												\
		ECS2::Entity::Id callOrderEntityId = GetComponent(systemEntityId)->id_;							\
		const ECS::File::Table::System::CallOrder::RunBefore* systemRunBefore = GetComponent(callOrderEntityId);	\
		return !systemRunBefore->systems_.empty();																													\
	}(systemE)

#define ECS__FILE__TABLE__SYSTEM__HAS_RUN_AFTER_SYSTEMS(systemE)																									\
	[this](ECS2::Entity::Id systemEntityId) -> bool {																												\
		ECS2::Entity::Id callOrderEntityId = GetComponent(systemEntityId)->id_;							\
		const ECS::File::Table::System::CallOrder::RunAfter* systemRunAfter = GetComponent(callOrderEntityId);		\
		return !systemRunAfter->systems_.empty();																													\
	}(systemE)


	template
	void ECS__FILE__TABLE__SYSTEM__ADD_RUN_BEFORE_SYSTEM(System* system, ECS2::Entity::Id systemEntityId, ECS2::Entity::Id runBeforeSystemEntityId) {
		if (system->template IsComponentExist(systemEntityId)) {
			ECS2::Entity::Id callOrderEntityId = system->template GetComponent(systemEntityId)->id_;
			if (system->template IsComponentExist(callOrderEntityId)) {
				ECS::File::Table::System::CallOrder::RunBefore* systemRunBefore = system->template GetComponent(callOrderEntityId);
				auto it = ::std::find_if(systemRunBefore->systems_.begin(), systemRunBefore->systems_.end(), [runBeforeSystemEntityId](auto& systemInfo) {
					/*Can be invalid.*/
					/*ASSERT(systemInfo.id_.IsValid());*/
					ASSERT(ECS::File::Table::IsValidName(systemInfo.name_));
					return systemInfo.id_ == runBeforeSystemEntityId;
					});
				if (it == systemRunBefore->systems_.end()) {
					systemRunBefore->systems_.push_back({ runBeforeSystemEntityId, GetFullName(system, runBeforeSystemEntityId, "::", false) });
				}
			}
		}
	}

	template
	void ECS__FILE__TABLE__SYSTEM__ADD_RUN_AFTER_SYSTEM(System* system, ECS2::Entity::Id systemEntityId, ECS2::Entity::Id runAfterSystemEntityId) {
		if (system->template IsComponentExist(systemEntityId)) {
			ECS2::Entity::Id callOrderEntityId = system->template GetComponent(systemEntityId)->id_;
			if (system->template IsComponentExist(callOrderEntityId)) {
				ECS::File::Table::System::CallOrder::RunAfter* systemRunAfter = system->template GetComponent(callOrderEntityId);
				auto it = ::std::find_if(systemRunAfter->systems_.begin(), systemRunAfter->systems_.end(), [runAfterSystemEntityId](auto& systemInfo) {
					/*Can be invalid.*/
					/*ASSERT(systemInfo.id_.IsValid());*/
					ASSERT(ECS::File::Table::IsValidName(systemInfo.name_));
					return systemInfo.id_ == runAfterSystemEntityId;
					});
				if (it == systemRunAfter->systems_.end()) {
					systemRunAfter->systems_.push_back({ runAfterSystemEntityId, GetFullName(system, runAfterSystemEntityId, "::", false) });
				}
			}
		}
	}

	template
	bool IsSystemDisabled(System* system, ECS2::Entity::Id systemEntityId) {
		return system->template IsComponentExist(systemEntityId);
	}

	template
	std::vector GetComponentFields(System* system, ECS2::Entity::Id ecsComponentEntityId) {

		std::vector ecsComponentFields;

		if (system->template IsComponentExist(ecsComponentEntityId)) {
			for (ECS2::Entity::Id fieldEntityId : system->template GetComponent(ecsComponentEntityId)->entityIds_) {
				ASSERT(system->template IsComponentExist(fieldEntityId));
				ecsComponentFields.push_back(fieldEntityId);
			}
		}

		return ecsComponentFields;
	}
}

