template
ECS2::Entity::Id ECS__GENERATOR__CREATE_WORLD_PARAMETER(System* system) {
	return CPP__TREE__DECL__CREATE_PARAMETER(
		system,
		CPP__TREE__TYPE__CREATE_TEMPLATE_SPECIALIZATION_TYPE(
			system,
			CPP__TREE__TYPE__CREATE_NAMED_TYPE(system, "std::shared_ptr"),
			std::vector{
		CPP__TREE__TYPE__CREATE_NAMED_TYPE(system, "ECS2::World")
	}),
		"world");
}

template
ECS2::Entity::Id CREATE_BEGIN_PROFILE_EXPR_STATEMENT(
	System* system,
	const std::string& str) {
	return CPP__TREE__STMT__CREATE_EXPRESSION_STATEMENT(
		system,
		CPP__TREE__EXPR__CREATE_MACRO_INVOCATION(
			system,
			"BEGIN_PROFILE",
			std::vector{
		CPP__TREE__EXPR__CREATE_LITERAL_EXPR(system, str, "")
	},
			ECS2::Entity::Id::invalid_));
}

template
ECS2::Entity::Id CREATE_END_PROFILE_EXPR_STATEMENT(System* system) {
	return CPP__TREE__STMT__CREATE_EXPRESSION_STATEMENT(
		system,
		CPP__TREE__EXPR__CREATE_MACRO_INVOCATION(
			system,
			"END_PROFILE",
			std::vector{},
			ECS2::Entity::Id::invalid_));
}

template
std::tuple<
	std::vector,
	std::vector,
	std::vector,
	std::vector,
	std::vector,
	std::vector,
	std::vector> ECS__GENERATOR__GET_FILE_TABLES(System* system, ECS2::Entity::Id fileEntityId) {

	std::vector fileStructs;
	std::vector fileConstants;
	std::vector fileComponents;
	std::vector fileSystems;
	std::vector fileEnums;
	std::vector fileArchetypes;//deprecated
	std::vector fileBundles;

	std::function getFileTables = [&](ECS2::Entity::Id entityId) {
		const ECS2::ComponentsFilter tableComponentsFilter = system->GetComponentsFilter(entityId);

		//Table is namespace.
		if (tableComponentsFilter.IsSet()) {
			for (ECS2::Entity::Id childTableEntityId : system->template GetComponent(entityId)->entityIds_) {
				getFileTables(childTableEntityId);
			}
		}
		else if (tableComponentsFilter.IsSet()) {
			fileSystems.push_back(entityId);
		}
		else if (tableComponentsFilter.IsSet()) {
			fileComponents.push_back(entityId);
		}
		else if (tableComponentsFilter.IsSet()) {
			fileStructs.push_back(entityId);
		}
		else if (tableComponentsFilter.IsSet()) {
			fileConstants.push_back(entityId);
		}
		//deprecated
		else if (tableComponentsFilter.IsSet()) {
			fileArchetypes.push_back(entityId);
		}
		else if (tableComponentsFilter.IsSet()) {
			fileBundles.push_back(entityId);
		}
		else if (tableComponentsFilter.IsSet()) {
			fileEnums.push_back(entityId);
		}
		else {
			ASSERT_FAIL();
		}
		};

	auto* fileTables = system->template GetComponent(fileEntityId);

	for (ECS2::Entity::Id tableEntityId : fileTables->entityIds_) {
		getFileTables(tableEntityId);
	}


	//Sort structs by theire definition order.
	std::sort(fileStructs.begin(), fileStructs.end(),
		[&](ECS2::Entity::Id first, ECS2::Entity::Id second) {
			const ECS2::ComponentsFilter firstCF = system->GetComponentsFilter(first);
			const Common::Index firstOrderIndex = system->template GetComponent(first)->orderIndex_;
			const ECS2::ComponentsFilter secondCF = system->GetComponentsFilter(second);
			const Common::Index secondOrderIndex = system->template GetComponent(second)->orderIndex_;
			return firstOrderIndex < secondOrderIndex;
		});
	std::sort(fileArchetypes.begin(), fileArchetypes.end(),
		[&](ECS2::Entity::Id first, ECS2::Entity::Id second) {
			const ECS2::ComponentsFilter firstCF = system->GetComponentsFilter(first);
			const Common::Index firstOrderIndex = system->template GetComponent(first)->orderIndex_;
			const ECS2::ComponentsFilter secondCF = system->GetComponentsFilter(second);
			const Common::Index secondOrderIndex = system->template GetComponent(second)->orderIndex_;
			return firstOrderIndex < secondOrderIndex;
		});

	return { fileStructs, fileConstants, fileComponents, fileSystems, fileEnums, fileArchetypes, fileBundles };

}

template
std::vector ECS__GENERATOR__GENERATE_HPP_INCLUDES(
	System* system,
	ECS2::Entity::Id fileEntityId,
	const std::filesystem::path& projectFilePath,
	const std::vector& fileStructs,
	const std::vector& fileComponents,
	const std::vector& fileConstants,
	const std::vector& fileArchetypes,
	const std::vector& fileSystems) {

	std::vector data = Resource::LoadFileAndGetContent(projectFilePath.string());

	::Lua::Context context;
	::Lua::Script script{ std::string{ data.data(), data.size() } };
	context.LoadScript(script);
	luabridge::LuaRef ecsTable = luabridge::getGlobal(context.state_, "ECS");
	ASSERT_FMSG(ecsTable.isTable(), "");
	luabridge::LuaRef includesTable = ecsTable["Includes"];


	std::unordered_set includes;

	includes.insert("lua.hpp");
	includes.insert("Common/ECS2/ECS2.hpp");
	includes.insert("chrono");
	includes.insert("tuple");
	includes.insert("OksEngine.IComponent.hpp");
	includes.insert("Common/Common.hpp");
	includes.insert("Common/Common.Bitset.hpp");

	includes.insert("luabridge3/LuaBridge/LuaBridge.h");
	includes.insert("Common/OS/OS.Assert.hpp");

	auto getIncludesByTypeName = [&](const std::string& typeName) {
		std::vector includes;
		if (includesTable.isTable()) {

			for (luabridge::Iterator it(includesTable); !it.isNil(); ++it) {
				// Каждый элемент таблицы — это LuaRef, который должен быть таблицей
				luabridge::LuaRef ruleTable = it.value();

				if (ruleTable.isTable()) {

					bool needToIncludeHeader = false;
					// Извлекаем массив "Entries"
					luabridge::LuaRef entriesRef = ruleTable["Entries"];
					if (entriesRef.isTable()) {
						for (luabridge::Iterator entIt(entriesRef); !entIt.isNil(); ++entIt) {
							// Значение должно быть строкой
							if (entIt.value().isString()) {
								std::string key = entIt.value().cast().value();
								if (typeName.find(key) != std::string::npos) {
									needToIncludeHeader = true;
								}
							}
						}
					}

					// Аналогично извлекаем массив "Headers"
					luabridge::LuaRef headersRef = ruleTable["Headers"];
					if (headersRef.isTable()) {
						for (luabridge::Iterator hdrIt(headersRef); !hdrIt.isNil(); ++hdrIt) {
							if (hdrIt.value().isString() && needToIncludeHeader) {
								includes.push_back(hdrIt.value().cast().value());
							}
						}
					}
				}
			}
		}
		return includes;
		};

	for (ECS2::Entity::Id ecsStructEntityId : fileStructs) {
		if (system->template IsComponentExist(ecsStructEntityId)) {
			for (ECS2::Entity::Id fieldEntityId : system->template GetComponent(ecsStructEntityId)->entityIds_) {
				auto structIncludes = getIncludesByTypeName(system->template GetComponent(fieldEntityId)->name_);
				for (auto include : structIncludes) {
					includes.insert(include);
				}
			}
		}
	}

	for (ECS2::Entity::Id ecsComponentEntityId : fileComponents) {
		if (system->template IsComponentExist(ecsComponentEntityId)) {
			for (ECS2::Entity::Id fieldEntityId : system->template GetComponent(ecsComponentEntityId)->entityIds_) {
				auto componentIncludes = getIncludesByTypeName(system->template GetComponent(fieldEntityId)->name_);
				for (auto include : componentIncludes) {
					includes.insert(include);
				}
			}
		}
	}

	for (ECS2::Entity::Id ecsConstantEntityId : fileConstants) {
		const std::string typeName = system->template GetComponent(ecsConstantEntityId)->type_;
		auto contantIncludes = getIncludesByTypeName(typeName);
		for (auto include : contantIncludes) {
			includes.insert(include);
		}
	}


	for (ECS2::Entity::Id archetypeEntityId : fileArchetypes) {
		const ECS2::ComponentsFilter archetypeCF = system->GetComponentsFilter(archetypeEntityId);
		ASSERT(archetypeCF.IsSet());

		std::vector componentEntityIds;
		if (archetypeCF.IsSet()) {
			auto* components = system-> template GetComponent(archetypeEntityId);
			for (std::string component : components->components_) {
				ECS2::Entity::Id componentEntityId = ECS::File::Table::GetTableEntityIdByName(system, archetypeEntityId, component);
				ECS2::Entity::Id ecsFileEntityId = ECS::File::Table::GetTableFileEntity(system, componentEntityId);
				const std::filesystem::path ecsFileIncludePath = ECS::File::Table::GetFileIncludePath(system, ecsFileEntityId, projectFilePath, ".hpp");

				includes.insert(ecsFileIncludePath.string());
			}
		}

		std::vector archetypeEntityIds;
		if (archetypeCF.IsSet()) {
			auto* archetypes = system->template GetComponent(archetypeEntityId);
			for (std::string archetype : archetypes->archetypes_) {
				ECS2::Entity::Id refArchetypeEntityId = ECS::File::Table::GetTableEntityIdByName(system, archetypeEntityId, archetype);
				ECS2::Entity::Id ecsFileEntityId = ECS::File::Table::GetTableFileEntity(system, refArchetypeEntityId);
				const std::filesystem::path ecsFileIncludePath = ECS::File::Table::GetFileIncludePath(system, ecsFileEntityId, projectFilePath, ".hpp");

				includes.insert(ecsFileIncludePath.string());
			}
		}
	}

	//Generate system component includes.
	for (ECS2::Entity::Id systemEntityId : fileSystems) {

		//if (ECS__FILE__TABLE__SYSTEM__IS_DISABLED(systemEntityId)) {
		//	continue;
		//}
		const std::string systemFullName = ECS::File::Table::GetFullName(system, systemEntityId, "::", false);

		if (system->template IsComponentExist(systemEntityId)) {
			ECS2::Entity::Id updateMethodEntityId
				= system->template GetComponent(systemEntityId)->id_;
			if (system->template IsComponentExist(updateMethodEntityId)) {
				::std::vector accessesEntities
					= system->template GetComponent(updateMethodEntityId)->entityIds_;
				for (ECS2::Entity::Id accessEntity : accessesEntities) {
					//archetype
					if (system->template IsComponentExist(accessEntity)) {
						const std::string archetypeLocalName = system->template GetComponent(accessEntity)->name_;
						ECS2::Entity::Id archetypeEntityId = ECS::File::Table::GetTableEntityIdByName(system, systemEntityId, archetypeLocalName);
						ECS2::Entity::Id fileEntityId = ECS::File::Table::GetTableFileEntity(system, archetypeEntityId);
						includes.insert(ECS::File::Table::GetFileIncludePath(system, fileEntityId, projectFilePath, ".hpp").string());
					}
				}
			}
		}

		std::vector allComponents = ECS::File::Table::GetComponentsEntityIds(system, systemEntityId);

		for (const ECS2::Entity::Id componentEntityId : allComponents) {
			ECS2::Entity::Id ecsFileEntityId = ECS::File::Table::GetTableFileEntity(system, componentEntityId);
			if (ecsFileEntityId == fileEntityId) {
				continue;
			}
			const std::filesystem::path ecsFileIncludePath = ECS::File::Table::GetFileIncludePath(system, ecsFileEntityId, projectFilePath, ".hpp");

			includes.insert(ecsFileIncludePath.string());
		}
	}

	std::vector includeNodeEntities;
	for (const std::string& include : includes) {
		includeNodeEntities.push_back(CPP__TREE__PREPROCESSOR__CREATE_INCLUDE(system, include));
	}

	return includeNodeEntities;
}


template
std::vector ECS__GENERATOR__GENERATE_CPP__INCLUDES(System* system, const std::filesystem::path& projectFilePath, ECS2::Entity::Id fileEntityId) {

	std::vector includeNodeEntities;

	const std::filesystem::path filePath = system->template GetComponent(fileEntityId)->path_;
	const std::filesystem::path correspondingHppFileIncludePath = ECS::File::Table::GetFileIncludePath(system, fileEntityId, projectFilePath, ".hpp");
	std::string correspondingHppFileIncludePathStr = correspondingHppFileIncludePath.generic_string();
	std::replace(correspondingHppFileIncludePathStr.begin(), correspondingHppFileIncludePathStr.end(), '\\', '/');
	includeNodeEntities.push_back(CPP__TREE__PREPROCESSOR__CREATE_INCLUDE(system, correspondingHppFileIncludePathStr));
	includeNodeEntities.push_back(CPP__TREE__PREPROCESSOR__CREATE_INCLUDE(system, "imgui.h"));
	includeNodeEntities.push_back(CPP__TREE__PREPROCESSOR__CREATE_INCLUDE(system, "misc/cpp/imgui_stdlib.h"));

	return includeNodeEntities;
}


namespace ECS::Generator
{

	template
	std::vector GENERATE_STRUCTS_FORWARD_DECLARATIONS(System* system, const std::vector& fileStructs) {

		std::vector structForwardDeclNodes;

		//Generate structs forward declarations .
		for (ECS2::Entity::Id structEntityId : fileStructs) {

			const ECS2::ComponentsFilter structCF = system->GetComponentsFilter(structEntityId);
			ASSERT(structCF.IsSet());

			const ECS2::Entity::Id cppStructEntityId = system->CreateEntity();
			const auto ecsParentTables = ECS::File::Table::GetTableParents(system, structEntityId);
			const auto [firstNamespaceEntityId, lastNamespaceEntityId] = CPP__TREE__CREATE_CPP_NAMESPACES(system, ecsParentTables, std::vector{cppStructEntityId});

			system->template CreateComponent(cppStructEntityId);
			system->template CreateComponent(cppStructEntityId);
			system->template CreateComponent(cppStructEntityId);
			system->template CreateComponent(cppStructEntityId, system->template GetComponent(structEntityId)->name_);

			if (lastNamespaceEntityId.IsValid()) {
				system->template CreateComponent(cppStructEntityId, lastNamespaceEntityId);
			}
			if (firstNamespaceEntityId.IsValid()) {
				structForwardDeclNodes.push_back(firstNamespaceEntityId);
			}
			else {
				structForwardDeclNodes.push_back(cppStructEntityId);
			}
		}

		return structForwardDeclNodes;

	}


	template
	std::vector GENERATE_CONSTANTS(System* system, const std::vector& fileConstants) {

		std::vector constantNodes;

		//Generate constants code tree.
		for (ECS2::Entity::Id constantEntityId : fileConstants) {
			const ECS2::ComponentsFilter constantCF = system->GetComponentsFilter(constantEntityId);
			ASSERT(constantCF.IsSet());

			const ECS2::Entity::Id cppConstantEntityId = system->CreateEntity();
			const auto parentTables = ECS::File::Table::GetTableParents(system, constantEntityId);
			const auto [firstNamespaceEntityId, lastNamespaceEntityId] = CPP__TREE__CREATE_CPP_NAMESPACES(system, parentTables, std::vector{cppConstantEntityId});

			CPP__TREE__DECL__CREATE_VARIABLE_COMPONENTS(system,
				cppConstantEntityId,
				CPP__TREE__TYPE__CREATE_NAMED_TYPE(system, system->template GetComponent(constantEntityId)->type_),
				system->template GetComponent(constantEntityId)->name_,
				CPP__TREE__EXPR__CREATE_LITERAL_EXPR(system, system->template GetComponent(constantEntityId)->value_, ""),
				lastNamespaceEntityId
			);

			system->template GetComponent(constantEntityId)->type_;

			if (firstNamespaceEntityId.IsValid()) {
				constantNodes.push_back(firstNamespaceEntityId);
			}
			else {
				constantNodes.push_back(cppConstantEntityId);
			}
		}

		return constantNodes;
	}

	template
	std::vector GENERATE_ENUMS(System* system, const std::vector& fileEnums) {
		std::vector enumsNodes;
		//Generate Enums code tree.
		for (ECS2::Entity::Id enumEntityId : fileEnums) {
			const ECS2::ComponentsFilter enumCF = system->GetComponentsFilter(enumEntityId);
			ASSERT(enumCF.IsSet());

			const ECS2::Entity::Id cppEnumEntityId = system->CreateEntity();
			const auto ecsParentTables = ECS::File::Table::GetTableParents(system, enumEntityId);
			const auto [firstNamespaceEntityId, lastNamespaceEntityId] = CPP__TREE__CREATE_CPP_NAMESPACES(system, ecsParentTables, std::vector{cppEnumEntityId});

			system->template CreateComponent(cppEnumEntityId);
			system->template CreateComponent(cppEnumEntityId);
			system->template CreateComponent(cppEnumEntityId);
			system->template CreateComponent(cppEnumEntityId, system->template GetComponent(enumEntityId)->name_);

			std::vector enumeratorEntityIds;
			for (const std::string value : system->template GetComponent(enumEntityId)->values_) {
				ECS2::Entity::Id enumeratorEntityId = system->CreateEntity();
				system->template CreateComponent(enumeratorEntityId);
				system->template CreateComponent(enumeratorEntityId);
				system->template CreateComponent(enumeratorEntityId, value, ECS2::Entity::Id::invalid_); // Without 
				system->template CreateComponent(enumeratorEntityId, value);
				system->template CreateComponent(enumeratorEntityId, cppEnumEntityId);
				enumeratorEntityIds.push_back(enumeratorEntityId);
			}
			system->template CreateComponent(cppEnumEntityId, enumeratorEntityIds);

			if (lastNamespaceEntityId.IsValid()) {
				system->template CreateComponent(cppEnumEntityId, lastNamespaceEntityId);
			}
			if (firstNamespaceEntityId.IsValid()) {
				enumsNodes.push_back(firstNamespaceEntityId);
			}
			else {
				enumsNodes.push_back(cppEnumEntityId);
			}
		}
		return enumsNodes;
	}

	template
	ECS2::Entity::Id GenerateCPPFile(System* system, const std::filesystem::path& ecsProjectfilePath, const std::filesystem::path& ecsFilePath) {
		//CPP File
		ECS2::Entity::Id cppFileEntityId = system->CreateEntity();
		std::vector cppFileNodeEntityIds;
		{
			system->template CreateComponent(cppFileEntityId);
			system->template CreateComponent(cppFileEntityId);

			//File PATH and NAME
			system->template CreateComponent(cppFileEntityId, ecsFilePath.parent_path().string());
			system->template CreateComponent(cppFileEntityId, "auto_" + ecsFilePath.stem().string());

		}

		return cppFileEntityId;
	}

