							std::vector childs;

							childs.push_back(CPP__TREE__DECL__CREATE_PARAMETER(this, CPP__TREE__TYPE__CREATE_NAMED_TYPE(this, "ECS2::Entity::Id"), "entityId"));

							childs.push_back(
								CPP__TREE__STMT__CREATE_COMPOUND_STATEMENT(this,
