        void CreateFileEntitiesSystem(std::shared_ptr world) {
            CreateFileEntities createFileEntities = world;
            ECS2::ComponentsFilter excludesForEntity0;
            excludesForEntity0.SetBits();
            world->ForEachEntity(
                excludesForEntity0,
                [&](ECS2::Entity::Id entity0Id, const ECS::Module::Tag *eCS__MODULE__TAG,
                    const ECS::Module::Path *eCS__MODULE__PATH, const Behaviour::LuaScript *bEHAVIOUR__LUASCRIPT) {
                    BEGIN_PROFILE("CreateFileEntities::Update");
                    createFileEntities.Update(entity0Id, eCS__MODULE__TAG, eCS__MODULE__PATH, bEHAVIOUR__LUASCRIPT);
                    END_PROFILE();
                });
        };
