    namespace Project {
        void CreateSystem(std::shared_ptr world) {
            Create create = world;
            ECS2::ComponentsFilter excludesForEntity0;
            excludesForEntity0.SetBits();
            world->ForEachEntity<::CommandLineParameters, ECS::Project::Path>(
                excludesForEntity0,
                [&](ECS2::Entity::Id entity0Id, const ::CommandLineParameters *__COMMANDLINEPARAMETERS,
                    const ECS::Project::Path *eCS__PROJECT__PATH) {
                    BEGIN_PROFILE("Create::Update");
                    create.Update(entity0Id, __COMMANDLINEPARAMETERS, eCS__PROJECT__PATH);
                    END_PROFILE();
                });
        };
    } // namespace Project
